private TreeNode<T> rotateRight(TreeNode<T> node) {
	// Error handling
	if (node == null) {
		throw new IllegalArgumentException("Cannot rotate a null node");
	}

	// Get the right child of the node
	TreeNode<T> rightChild = node.getRight();

	// Check if the right child is null
	if (rightChild == null) {
		throw new IllegalStateException("Cannot rotate a node with a null right child");
	}

	// Get the left child of the right child
	TreeNode<T> leftGrandChild = rightChild.getLeft();

	// Check if the left grand child is null
	if (leftGrandChild == null) {
		throw new IllegalStateException("Cannot rotate a node with a null left grand child");
	}

	// Perform the rotation
	node.setRight(leftGrandChild);
	rightChild.setLeft(node);

	return leftGrandChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }

    // Save the current right child and its left child
    TreeNode<T> rightChild = node.right;
    TreeNode<T> rightChildLeft = rightChild.left;

    // Set the new right child of the current node to its left child
    node.right = rightChildLeft;

    // Set the parent of the right child's left child to the current node
    if (rightChildLeft != null) {
        rightChildLeft.parent = node;
    }

    // Set the new parent of the right child to the parent of the current node
    rightChild.parent = node.parent;

    // Update the parent pointers
    if (node.parent != null) {
        if (node.parent.left == node) {
            node.parent.left = rightChild;
        } else {
            node.parent.right = rightChild;
        }
    }

    // Update the left child of the current node
    node.left = rightChild;

    // Set the new left child of the right child to the current node
    rightChild.left = node;

    return rightChild;
}

