private TreeNode<T> rotateRight(TreeNode<T> node) {
    // step 1: find the parent of the node
    TreeNode<T> parent = node.getParent();

    // step 2: find the left child of the node
    TreeNode<T> leftChild = node.getLeftChild();

    // step 3: find the right child of the left child
    TreeNode<T> rightChild = leftChild.getRightChild();

    // step 4: update the tree structure
    node.setParent(leftChild);
    leftChild.setRightChild(node);
    node.setLeftChild(rightChild);

    // step 5: update the parent of the left child
    leftChild.setParent(parent);

    // step 6: return the new parent of the node
