public static void addToClassPath(Vector<URL> cpV, String dir) {
	try {
		File[] files = new File(dir).listFiles();
		if (files == null) {
			throw new FileNotFoundException("Directory does not exist or is not accessible: " + dir);
		}

		for (File file : files) {
			if (file.isFile() && file.getName().endsWith(".jar")) {
				cpV.add(file.toURI().toURL());
			}
		}
	} catch (MalformedURLException e) {
		throw new RuntimeException("Error while adding to classpath: " + dir, e);
	}
}

public static void addToClassPath(Vector<URL> cpV, String dir) throws MalformedURLException {
    // Check if directory exists
    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Directory does not exist or is not a directory: " + dir);
    }

    // Get all jar files in the directory and its subdirectories
    File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
        public boolean accept(File dir, String name) {
            return name.toLowerCase().endsWith(".jar");
        }
    });

    // Add all jar files to the classpath
    for (File jarFile : jarFiles) {
        try {
            cpV.add(new URL("file://" + jarFile.getAbsolutePath()));
        } catch (MalformedURLException e) {
            throw new IllegalStateException("Invalid jar file URL: " + jarFile.getAbsolutePath(), e);
        }
    }
}

