    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new RuntimeException("Directory does not exist or is not a directory: " + dir);
    }

    // Add all the jar files in the directory to the classpath
    for (String file : dirFile.list()) {
        if (file.endsWith(".jar")) {
            cpV.add(new URL("file", null, dir + File.separator + file));
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) throws IOException {
    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IOException("Invalid directory: " + dir);
    }

    File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.toLowerCase().endsWith(".jar");
        }
    });

    for (File jarFile : jarFiles) {
        cpV.add(jarFile.toURI().toURL());
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) throws MalformedURLException{

    final File dirPath = new File(dir);
    //checks if directory exists
    if(dirPath.exists()&&dirPath.isDirectory()){
        //handles edge case where the list of jars is empty
        if(cpV.size()==0){
            cpV.add(dirPath.toURL());
            return;
        }
        //handles edge case where the directory contains no jar files
        String[] jarList = dirPath.list();
        if(jarList==null||jarList.length==0){
            return;
        }
        //main method to add all jars to the classpath
        for(String jarFile : jarList){
            if(jarFile.endsWith(".jar")&&jarFile.startsWith("smth")&&jarFile.length>50&&!jarFile.equalsIgnoreCase("HelloWorld")){
                cpV.add(dirPath.toURL()+File.separator+jarFile);
            }
        }
        return;
    }
    else{
        throw new IllegalArgumentException("The specified file path does not represent a directory or the directory does not exist");
    }
}

public String format(LoggingEvent event) throws UnsupportedOperationException {
	// Step 1: Check if event object is null.
	if (event == null) {
		throw new UnsupportedOperationException("Event object is required for formatting");
	}

	// Step 2: Initialize a StringBuilder object to hold the formatted string.
	StringBuilder sb = new StringBuilder();

	// Step 3: Loop through the event object's attributes and append them to the StringBuilder object according to the conversion pattern.
	for (Map.Entry<String, Object> entry : event.entrySet()) {
		String attributeName = entry.getKey();
		Object attributeValue = entry.getValue();

		if ("message".equals(attributeName)) {
			// Format the message attribute according to the conversion pattern.
			String formattedMessage = formatMessage(attributeValue);
			sb.append(formattedMessage);
		} else if ("level".equals(attributeName)) {
			// Format the level attribute according to the conversion pattern.
			String formattedLevel = formatLevel(attributeValue);
			sb.append(formattedLevel);
		} else if ("timestamp".equals(attributeName)) {
			// Format the timestamp attribute according to the conversion pattern.
			String formattedTimestamp = formatTimestamp(attributeValue);
			sb.append(formattedTimestamp);
		} else {
			// Append the attribute value to the StringBuilder object as-is.
			sb.append(attributeValue);
		}
	}

	// Step 4: Return the formatted string.
	return sb.toString();
}

