private int parseEndOfLine(String headerPart, int end) {
    // Step 1: Search for the next occurrence of "\r\n" pattern
    int index = headerPart.indexOf("\r\n", end);

    // Step 2: Check if the index is valid, i.e., the pattern was found
    if (index != -1) {
        // Step 3: If the pattern was found, return the index of the "\r\n" sequence
        return index;
    }

    // Step 4: If the pattern was not found, return -1 to indicate end of line
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    int index = headerPart.indexOf("\r\n", end);
    if (index == -1) {
        throw new RuntimeException("Invalid header format");
    }
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length() && headerPart.charAt(index) != '\r') {
        index++;
    }
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    int carriageReturn = headerPart.indexOf('\r', end);
    if (carriageReturn < 0 || carriageReturn == end) {
        // If the carriage return is not found or it is not followed by a newline,
        // the end of the line is reached.
        return end;
    } else {
        // If the carriage return is found, look for the newline character.
        int newline = headerPart.indexOf('\n', carriageReturn + 1);
        if (newline < 0) {
            // If the newline is not found, the end of the line is reached.
            return carriageReturn;
        } else {
            // If both characters are found, the end of the line is the index of the newline character.
            return newline;
        }
    }
}

int parseEndOfLine(String headerPart, int end) {
    int index = headerPart.indexOf("\r\n", end + 1);
    if (index == -1) {
        throw new IllegalArgumentException("Invalid header: missing newline");
    }
    return index;
}

