public void write(byte b[]) throws IOException {
    // Check for null or empty array
    if (b == null || b.length == 0) {
        return;
    }

    // Write bytes to output stream
    for (int i = 0; i < b.length; i++) {
        out.write(b[i]);
    }
}

@Override
public void write(byte b[]) throws IOException {
    // Handle edge case: If the byte array is empty, return immediately
    if (b.length == 0) {
        return;
    }

    // Handle edge case: If the output stream is closed, throw an IOException
    if (isClosed()) {
        throw new IOException("Stream is closed");
    }

    try {
        // Write the bytes to the output stream
        for (byte aB : b) {
            out.write(aB);
        }
    } catch (IOException e) {
        // If an IOException occurs, close the output stream and re-throw the exception
        close();
        throw e;
    }
}

@Override
public void write(byte b[]) throws IOException {
    // Check if the input array is null or has a negative length
    if (b == null || b.length < 0) {
        throw new IOException("Invalid input byte array");
    }

    // Write the bytes to the output stream
    for (int i = 0; i < b.length; i++) {
        out.write(b[i]);
    }
}

