        IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();
        for (int i = 0; i < graph.getVertices().size(); i++) {
            mapping.put(graph.getVertices().get(i), graph.getVertices().get(i));
        }
        return mapping;
     }

