    // Create a new graph and copy the vertices and edges from the input graph
    Graph<V, E> newGraph = new Graph<>(graph.getVertexCount());
    newGraph.addVertices(graph.getVertices());
    newGraph.addEdges(graph.getEdges());

    // Create a mapping from each vertex in the new graph to itself
    Map<V, V> mapping = new HashMap<>();
    for (V vertex : newGraph.getVertices()) {
        mapping.put(vertex, vertex);
    }

    return new IsomorphicGraphMapping<>(newGraph, mapping);
}

