public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        deleteFile(file);
    }

    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {

  // Check if file is a directory
  if (file.isDirectory()) {

    // If file is a directory, delete all sub-directories and files
    for (File child : file.listFiles()) {
      forceDeleteOnExit(child);
    }
  }

  // Schedule file to be deleted when JVM exits
  file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File child : files) {
                forceDeleteOnExit(child);
            }
        }
    }

    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {

    // Check that the file is not null
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    // Delete the file and all sub-directories if it is a directory
    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        boolean deleted = file.delete();
        if (!deleted) {
            throw new IOException("Unable to delete file: " + file);
        }
    }

    // Register the file for deletion on exit
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        if (!file.delete()) {
            throw new IOException(String.format("Failed to delete file %s", file.getAbsolutePath()));
        }
    }
}

