public static int writeDelimitedTo(OutputStream out, Object message, Schema<Object> schema, LinkedBuffer buffer) throws IOException {
    // Check that the message and schema are not null
    if (message == null || schema == null) {
        throw new IllegalArgumentException("Message and schema cannot be null");
    }

    // Write the message length to the output stream
    out.write(ByteBuffer.allocate(4).putInt(0, schema.sizeof(message)).array());

    // Serialize the message into a LinkedBuffer
    ByteBuffer serializedMessage = schema.serialize(message, buffer);

    // Write the serialized message to the output stream
    out.write(serializedMessage.array());

    // Return the size of the message
    return serializedMessage.capacity();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message into the buffer first
    int messageSize = schema.computeSerializedSize(message, buffer);
    // Write the length of the message to the output stream
    out.writeInt(messageSize);
    // Write the message data to the output stream
    schema.writeTo(out, message, buffer);
    // Return the size of the message
    return messageSize;
}

