public class SerializableUtils {
    /**
     * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
     * @return the size of the message
     */
    public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        // Validate input
        if (out == null) {
            throw new IllegalArgumentException("OutputStream cannot be null");
        }
        if (message == null) {
            throw new IllegalArgumentException("Message cannot be null");
        }
        if (schema == null) {
            throw new IllegalArgumentException("Schema cannot be null");
        }
        if (buffer != null && buffer.size() < 16) {
            throw new IllegalArgumentException("Buffer too small");
        }

        // Serialize the message to a buffer
        byte[] bytes = schema.serialize(message, buffer, false);
        if (bytes == null) {
            throw new IOException("Failed to serialize message");
        }

        // Write the length of the message
        out.write((bytes.length & 0xFF000000) >>> 24);
        out.write((bytes.length & 0x00FF0000) >>> 16);
        out.write((bytes.length & 0x0000FF00) >>> 8);
        out.write(bytes.length & 0x000000FF);

        // Write the message data
        out.write(bytes, 0, bytes.length);

        return bytes.length;
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        // Validate the parameters
        if (out == null) {
            throw new IllegalArgumentException("OutputStream cannot be null");
        }
        if (message == null) {
            throw new IllegalArgumentException("Message cannot be null");
        }
        if (schema == null) {
            throw new IllegalArgumentException("Schema cannot be null");
        }
        if (buffer == null) {
            buffer = LinkedBuffer.defaultBuffer();
        }

        // Serialize the message
        int size = schema.serializedSize(message, buffer);
        buffer.writeTo(out);
        out.write(size);
        out.flush();

        return size;
    }

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.calculateSize(message);
    out.write(size);
    schema.writeTo(message, out, buffer);
    return size;
}

