public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Class<?>[] arguments = parameterizedType.getActualTypeArguments();

    // Check if the target type is a raw type and if so, return the bound type
    if (targetType.isAssignableFrom(parameterizedType.getRawType())) {
        return arguments;
    }

    // Check if the target type is a type variable and if so, recursively resolve the type arguments
    if (targetType.isAssignableFrom(parameterizedType.getOwnerType())) {
        return resolveArguments(targetType.getTypeParameters()[0], targetType.getDeclaringClass());
    }

    // If none of the above cases match, return null to indicate that the arguments cannot be resolved
    return null;
}

// Step 1: Check if the genericType is parameterized
if (!(genericType instanceof ParameterizedType)) {
    return null;
}

// Step 2: Get the type parameters for the targetType
Type[] typeParameters = targetType.getTypeParameters();

// Step 3: Get the actual type arguments for the genericType
Type[] actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

// Step 4: Create a map of type parameters to their corresponding actual type arguments
Map<String, Type> typeMap = new HashMap<>();
for (int i = 0; i < typeParameters.length; i++) {
    typeMap.put(typeParameters[i].getTypeName(), actualTypeArguments[i]);
}

// Step 5: Return the resolved arguments
Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
for (int i = 0; i < resolvedArguments.length; i++) {
    Type type = actualTypeArguments[i];
    if (type instanceof Class) {
        resolvedArguments[i] = (Class<?>) type;
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        String typeName = typeVariable.getTypeName();
        // If the type variable is not in the map, it means it is not parameterized
        if (!typeMap.containsKey(typeName)) {
            return null;
        }
        resolvedArguments[i] = (Class<?>) typeMap.get(typeName);
    }
}

return resolvedArguments;

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] argumentClasses = new Class<?>[typeArguments.length];

    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        argumentClasses[i] = resolveType(typeArgument, targetType.getTypeParameters()[i]);
    }

    return argumentClasses;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type actualTypeArgument = actualTypeArguments[i];
            if (actualTypeArgument instanceof TypeVariable) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
                TypeVariable<? extends Class<?>> bound = typeVariable.getBounds()[0];
                Type targetBound = TypeUtils.substituteTypeVariables(targetType, bound);
                resolvedArguments[i] = targetBound;
            } else {
                resolvedArguments[i] = actualTypeArgument;
            }
        }
        return resolvedArguments;
    } else {
        return null;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the actual type arguments
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Create an array to hold the resolved arguments
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

    // Iterate over the type arguments and resolve each argument using the target type
    for (int i = 0; i < typeArguments.length; i++) {
        // Get the type argument
        Type typeArgument = typeArguments[i];

        // Check if the type argument is a type variable
        if (typeArgument instanceof TypeVariable) {
            // Get the type variable
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;

            // Try to resolve the type variable using the target type
            resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
        } else {
            // The type argument is not a type variable, so it is already resolved
            resolvedArguments[i] = (Class<?>) typeArgument;
        }
    }

    // Return the resolved arguments
    return resolvedArguments;
}

