    cache.compute(data.getKey(), (key, value) -> {
        if (value == null) {
            // If the key does not exist in the cache, create a new value
            value = new METRICSReader();
            value.setData(data);
            return value;
        } else {
            // If the key already exists in the cache, merge the new data with the existing value
            value.merge(data);
