public void addAndMerge(METRICS data) {
    // Check if the data is null
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }

    // Merge the new data with the existing value
    METRICS existingValue = get(data.getKey());
    if (existingValue == null) {
        // If there is no existing value, simply add the new data
        super.add(data);
    } else {
        // Merge the new data with the existing value
        METRICS mergedValue = merge(existingValue, data);
        super.set(data.getKey(), mergedValue);
    }
}

public void accept(final METRICS data) {
  // Check if the data is null; if so, do not accept it
  if (data == null) {
    return;
  }

  // Check if the data is already in the cache; if so, merge it with the existing value
  METRICS existingData = cache.get(data.getKey());
  if (existingData != null) {
    // Merge the data with the existing value
    METRICS mergedData = mergeData(existingData, data);
    cache.put(data.getKey(), mergedData);
  } else {
    // If the data is not already in the cache, add it
    cache.put(data.getKey(), data);
  }
}

public void accept(METRICS data) {
    // Step 1: Check if the data to be added is null or not
    if (data == null) {
        return;
    }

    // Step 2: Check if the cache is empty
    if (cache == null || cache.length == 0) {
        // If the cache is empty, add the data to the cache
        cache = new METRICS[1];
        cache[0] = data;
        return;
    }

    // Step 3: Find the maximum value in the cache
    int maxIndex = 0;
    for (int i = 1; i < cache.length; i++) {
        if (cache[i] == null) {
            continue;
        }
        if (data.compareTo(cache[maxIndex]) > 0) {
            maxIndex = i;
        }
    }

    // Step 4: Merge the data into the cache
    cache[maxIndex] = data;

    // Step 5: If the cache is full, remove the smallest value
    if (cache.length == maxIndex + 1) {
        cache[0] = null;
        for (int i = 1; i < cache.length; i++) {
            cache[i - 1] = cache[i];
        }
    }
}

void insertBefore(Bucket bucket) {
    // Check if the bucket is currently in the data structure
    if (bucket == null) {
        throw new NullPointerException("Cannot insert before null bucket");
    }

    // Find the position of the current bucket in the data structure
    int currentPosition = findBucketPosition(bucket);

    // If the current bucket is not found, throw an exception
    if (currentPosition == -1) {
        throw new IllegalArgumentException("Bucket not found in data structure");
    }

    // Find the position of the bucket before which the current bucket should be inserted
    int previousPosition = currentPosition - 1;

    // If the bucket before which the current bucket should be inserted is not found, throw an exception
    if (previousPosition < 0) {
        throw new IllegalStateException("Bucket not found before current bucket");
    }

    // Update the position of the current bucket and the bucket before which it should be inserted
    bucket.setPosition(previousPosition);
    currentBucket.setPosition(currentPosition);
}

