        throw new IllegalStateException("Bucket already in data structure");
    }

    // Check if this bucket is already in the data structure
    if (!contains(this)) {
        throw new IllegalStateException("This bucket not in data structure");
    }

    // Insert this bucket before the given bucket
    // Use a temporary variable to store the previous bucket
    Bucket prevBucket = getPreviousBucket(bucket);
    setPreviousBucket(prevBucket, this);
    setNextBucket(this, bucket);
}

