    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }

    // Check if the current bucket is null
    if (this == null) {
        throw new IllegalStateException("Cannot insert before a null bucket");
    }

    // Insert the bucket before the current bucket
    Bucket temp = this.previous;
    this.previous = bucket;
    bucket.next = temp;

    // Update the previous and next pointers of the new bucket
    bucket.previous = temp;
    temp.next = bucket;
