public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        // If the mappings object is null, we return an empty map
        return new HashMap<>();
    }

    Mappings diff = new Mappings();

    // We iterate over each field in the mappings object
    for (String field : mappings.keySet()) {
        // We check if the field exists in the input mapping
        if (!tableName.contains(field)) {
            // If the field does not exist, we add it to the diff object
            diff.put(field, mappings.get(field));
        }
    }

    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the existing mappings from the current index
    GetMappingsRequest request = new GetMappingsRequest();
    request.indices(tableName);
    Mappings existingMappings = client.admin().indices().getMappings(request).actionGet();

    // Remove _source config from the existing mappings
    existingMappings.removeSourceConfig(tableName);

    // Find the differences between the existing mappings and the input mappings
    Set<String> existingFields = existingMappings.get(tableName).fieldNames();
    Set<String> inputFields = mappings.get(tableName).fieldNames();
    Set<String> diffFields = Sets.difference(inputFields, existingFields);

    // Create a new mapping with the fields that do not exist in the input mappings
    MappingBuilder builder = new MappingBuilder();
    for (String diffField : diffFields) {
        builder.startObject(diffField, existingMappings.get(tableName));
    }
    Mappings newMappings = new Mappings(builder, existingMappings);

    return newMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null || mappings.isEmpty()) {
        // No difference found. Return an empty mapping.
        return new Mappings();
    }

    // Create a new mapping object to store the differences.
    Mappings differences = new Mappings();

    // Iterate over the input mapping fields.
    for (Map.Entry<String, Object> entry : mappings.entrySet()) {
        String fieldName = entry.getKey();
        Object fieldValue = entry.getValue();

        // Check if the field name starts with an underscore.
        if (fieldName.startsWith("_")) {
            // Remove the _source config from the differences.
            differences.remove(fieldName);
        } else {
            // Add the field to the differences.
            differences.put(fieldName, fieldValue);
        }
    }

    return differences;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Step 1: Get history mapping from current index
    Mappings historyMappings = getHistoryMappingsFromCurrentIndex(tableName);

    // Step 2: Get all fields from history mapping
    Set<String> historyMappingFields = historyMappings.get("properties").keySet();

    // Step 3: Get all fields from input mapping
    Set<String> inputMappingFields = mappings.get("properties").keySet();

    // Step 4: Calculate the difference between history mapping fields and input mapping fields
    Set<String> difference = new HashSet<>(historyMappingFields);
    difference.removeAll(inputMappingFields);

    // Step 5: Create new Mappings object with only the difference fields
    Mappings diffMappings = new Mappings();
    Set<Mapping> diffMappingSet = new HashSet<>();
    for (String fieldName : difference) {
        Mapping field = historyMappings.get("properties").get(fieldName);
        if (field != null) {
            diffMappingSet.add(new Mapping(field.getName(), field.getType, field.getFormat, null).setAs("properties"));
        }
    }
    diffMappings.get("properties").putAll(diffMappingSet);

    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Check if the input mappings is null or if the table name is empty
    if (mappings == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Input mappings or table name cannot be null or empty");
    }

    // Get the field names from the input mappings
    Set<String> fieldNames = new HashSet<>();
    for (Map.Entry<String, FieldProperties> entry : mappings.getProperties().entrySet()) {
        fieldNames.add(entry.getKey());
    }

    // Create a new Mappings object to store the diff structure
    Mappings diffMappings = new Mappings();

    // Iterate over the fields in the input mappings
    for (String fieldName : fieldNames) {
        // Check if the field exists in the current index
        if (!mappings.getProperties().containsKey(fieldName)) {
            // If the field does not exist, add it to the diff structure
            diffMappings.getProperties().put(fieldName, null);
        }
    }

    return diffMappings;
}

