public long readLong(int offset) throws IOException {
    // Check if the offset is beyond the limit
    if (offset < 0 || offset + 8 > classReader.length) {
        throw new IOException("Offset " + offset + " is beyond the limit");
    }

    // Read the bytes of the long value
    byte[] bytes = classReader.readBytes(offset, 8);

    // Convert the bytes to a long value
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value |= ((long) bytes[i] & 0xff) << (8 * i);
    }

    return value;
}

public long readLong(final int offset) {
    // Check if the offset is within the bounds of the class file
    if (offset < 0 || offset + 8 > this.length) {
        throw new IndexOutOfBoundsException("Offset is outside of the class file");
    }

    // Read the long value from the given offset
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value <<= 8;
        value |= this.bytes[offset + i] & 0xFF;
    }

    // Return the read value
    return value;
}

