        long value = 0;
        for (int i = 0; i < 8; i++) {
            int byteValue = readByte(offset + i) & 0xFF;
            value |= (byteValue << (i * 8));
        }
        return value;
    } catch (IOException e) {
        throw new RuntimeException("Error reading long value", e);
    }
}

