public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long fetchDataDuration = FETCH_DATA_DURATION;

    // If the start time is less than the fetch data duration,
    // generate a TimeRange for the remaining amount of time
    if (start < fetchDataDuration) {
        timeRanges.add(new TimeRange(start, fetchDataDuration));
        start = 0;
    }

    // If the end time is greater than the fetch data duration,
    // split the range into two TimeRanges
    if (end > fetchDataDuration) {
        timeRanges.add(new TimeRange(start, fetchDataDuration));
        timeRanges.add(new TimeRange(0, end - fetchDataDuration));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    long startTime = start;
    long endTime = end;
    while (startTime + duration <= endTime) {
        TimeRange timeRange = new TimeRange(startTime, startTime + duration);
        timeRanges.add(timeRange);
        startTime += duration;
    }
    if (startTime < endTime) {
        timeRanges.add(new TimeRange(startTime, endTime));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the number of time ranges based on the start time and end time
    int numTimeRanges = (int) Math.ceil((end - start) / FETCH_DATA_DURATION);

    for (int i = 0; i < numTimeRanges; i++) {
        // Calculate the start time of the current time range
        long rangeStart = start + (i * FETCH_DATA_DURATION);

        // Calculate the end time of the current time range
        long rangeEnd = (i == numTimeRanges - 1) ? end : (rangeStart + FETCH_DATA_DURATION);

        // Add the time range to the list
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
    }

    return timeRanges;
}

public static List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long currentStart = start;
    long currentEnd = Math.min(start + FETCH_DATA_DURATION, end);

    while (currentEnd < end) {
      timeRanges.add(new TimeRange(currentStart, currentEnd));

      currentStart = currentEnd + 1;
      currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
    }

    timeRanges.add(new TimeRange(currentStart, end));

    return timeRanges;
  }

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = FETCH_DATA_DURATION;

    while (end - start > fetchDataDuration) {
        long currentStart = start;
        long currentEnd = currentStart + fetchDataDuration;

        if (currentEnd > end) {
            currentEnd = end;
        }

        TimeRange timeRange = new TimeRange(currentStart, currentEnd);
        timeRanges.add(timeRange);

        start = currentEnd + 1; //increment the start time by 1 so that it's not the same as the end time
    }

    return timeRanges;
}

