public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the epoch day for the given time bucket
    long epochDay = timeBucket / 10000;

    // Calculate the day offset for the given day step
    int dayOffset = dayStep % 10;

    // Calculate the day of the month for the given time bucket
    int dayOfMonth = (int) ((timeBucket % 10000) / 100);

    // Calculate the new epoch day based on the day offset and day of the month
    long newEpochDay = epochDay + dayOffset - dayOfMonth;

    // Return the new epoch day as the compressed time bucket
    return newEpochDay * 10000;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day of the month
    int dayOfMonth = (int) (timeBucket % 100);

    // Calculate the month
    int month = (int) ((timeBucket / 100) % 100);

    // Calculate the year
    int year = (int) (timeBucket / 10_000);

    // Calculate the new day of the month
    int newDayOfMonth = dayOfMonth - dayStep;

    // If the new day of the month is less than 1, add it to the month
    if (newDayOfMonth < 1) {
        newDayOfMonth = month + newDayOfMonth;
    }

    // If the new day of the month is greater than the last day of the month, set it to the last day of the month
    if (newDayOfMonth > lastDayOfMonth(year, month)) {
        newDayOfMonth = lastDayOfMonth(year, month);
    }

    // Return the compressed time bucket
    return (long) (year * 10_000 + month * 100 + newDayOfMonth);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the time bucket value with the day step
    long timeBucketValue = timeBucket % dayStep;

    // Calculate the day offset based on the time bucket value and the day step
    long dayOffset = timeBucketValue / dayStep;

    // Calculate the new time bucket value by adding the day offset to the original time bucket value
    long newTimeBucketValue = timeBucketValue + dayOffset;

    return newTimeBucketValue;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    return (timeBucket / dayStep) * dayStep;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if the time bucket is valid
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Invalid time bucket");
    }

    // Check if the day step is valid
    if (dayStep < 1 || dayStep > 32) {
        throw new IllegalArgumentException("Invalid day step");
    }

    // Re-format the time bucket
    long newTimeBucket = timeBucket / (long)Math.pow(10, (dayStep - 1));

    // Check if the new time bucket is valid
    if (newTimeBucket < 0) {
        throw new IllegalStateException("Invalid new time bucket");
    }

    // Return the re-formatted time bucket
    return newTimeBucket;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int utf8Size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            utf8Size++;
        } else if (ch < 0x800) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            i++;
            utf8Size += 4;
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x007F) {
            utf8Size++;
        } else if (c <= 0x07FF) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate(c)) {
            utf8Size += 4;
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    // Handle edge case where the string is null or the index is out of bounds
    if (str == null || index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Invalid input: str is null or the index is out of bounds");
    }

    // Handle edge case where the length is negative or the index and length are out of bounds
    if (len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input: the length is negative or the index and length are out of bounds");
    }

    int utf8Size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x007F) {
            utf8Size++;
        } else if (c <= 0x07FF) {
            utf8Size += 2;
        } else if (Character.isSurrogate(c)) {
            if (Character.isHighSurrogate(c)) {
                i++;
                if (!Character.isLowSurrogate(str.charAt(i))) {
                    throw new IllegalArgumentException("Invalid input: surrogate pair is not well-formed");
                }
                utf8Size += 4;
            } else {
                utf8Size += 3;
            }
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int totalSize = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            totalSize++;
        } else if (c <= 0x7FF) {
            totalSize += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            totalSize += 4;
        } else {
            totalSize += 3;
        }
    }
    return totalSize;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("index must be within the range of 0 and str.length()");
    }
    if (len < 0 || len > str.length() - index) {
        throw new IllegalArgumentException("len must be non-negative and no greater than str.length() - index");
    }

    int utf8Size = 0;
    for (int i = index; i < index + len; i++) {
        utf8Size += str.charAt(i) <= 0x7F ? 1 : (str.charAt(i) <= 0x7FF ? 2 : (str.charAt(i) <= 0xFFFF ? 3 : 4));
    }
    return utf8Size;
}

