public static String sub(String str, int start, int end) {
    if (str == null || start < 0 || end < 0) {
        return null;
    }
    if (start > str.length() || end > str.length()) {
        return null;
    }
    try {
        return str.substring(start, end);
    } catch (IndexOutOfBoundsException e) {
        return null;
    }
}

