public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null) {
        // If the input array is null, fill in the byte vector with nullbytes
        for (int i = 0; i < byteLength; i++) {
            bytes[i + byteOffset] = 0x00;
        }
    } else {
        // Copy the input array into this byte vector
        System.arraycopy(byteArrayValue, byteOffset, bytes, 0, byteLength);
    }

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) {
    // Check for null byte array
    if (byteArrayValue == null) {
        // Fill the byte vector with null bytes
        for (int i = 0; i < byteLength; i++) {
            this.putByte((byte) 0);
        }
        return this;
    }

    // Check the byte offset and length are valid
    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byte offset and/or length provided");
    }

    // Copy the bytes from the byte array into the byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        this.putByte(byteArrayValue[i]);
    }

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.add((byte) 0);
        }
    } else {
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            this.add(byteArrayValue[i]);
        }
    }
    return this;
}

