public static AtmosphereRequest wrap(HttpServletRequest request) {
    // Check for null request
    if (request == null) {
        throw new IllegalArgumentException("Request cannot be null");
    }

    // Wrap the HTTP servlet request in an Atmosphere request
    AtmosphereRequest atmosphereRequest = new AtmosphereRequest(request);

    // Set the Atmosphere request method based on the HTTP request method
    switch (request.getMethod()) {
        case "GET":
            atmosphereRequest.setMethod(AtmosphereRequest.METHOD_GET);
            break;
        case "POST":
            atmosphereRequest.setMethod(AtmosphereRequest.METHOD_POST);
            break;
        case "PUT":
            atmosphereRequest.setMethod(AtmosphereRequest.METHOD_PUT);
            break;
        case "DELETE":
            atmosphereRequest.setMethod(AtmosphereRequest.METHOD_DELETE);
            break;
        default:
            throw new IllegalArgumentException("Unsupported request method: " + request.getMethod());
    }

    // Set the Atmosphere request path info based on the HTTP request path info
    atmosphereRequest.setPathInfo(request.getPathInfo());

    // Set the Atmosphere request query parameters based on the HTTP request query string
    List<NameValuePair> queryParams = UrlEncodedUtils.parse(request.getQueryString(), Charset.forName("UTF-8"));
    for (NameValuePair queryParam : queryParams) {
        atmosphereRequest.setQueryParameter(queryParam.getName(), queryParam.getValue());
    }

    // Set the Atmosphere request headers based on the HTTP request headers
    Map<String, String> headers = new HashMap<>();
    Enumeration headerNames = request.getHeaderNames();
    while (headerNames.hasMoreElements()) {
        String headerName = (String) headerNames.nextElement();
        headers.put(headerName, request.getHeader(headerName));
    }
    atmosphereRequest.setHeaders(headers);

    // Set the Atmosphere request input stream based on the HTTP request input stream
    atmosphereRequest.setInputStream(request.getInputStream());

    return atmosphereRequest;
}

