LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        // Write a null byte to indicate the end of the string
        lb.data().writeByte(0);
        return lb;
    }

    // Get the number of characters in the string
    int len = str.length();

    // Write the length of the string in bytes, not including the null terminator
    lb.data().writeShort(len);

    // Write the bytes of the string
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        lb.data().writeByte(c);
    }

    // Write the null terminator
    lb.data().writeByte(0);

    return lb;
}

public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws UTFDataFormatException {
    if (str == null) {
        throw new NullPointerException("String to write cannot be null");
    }
    if (lb == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }
    if (session == null) {
        throw new NullPointerException("WriteSession cannot be null");
    }
    // validate the string
    if (str.length() == 0) {
        throw new IllegalArgumentException("String to write cannot be empty");
    }
    // create a new LinkedBuffer and fill it with the utf8-encoded bytes from the string
    lb.clear();
    int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        // each UTF-8 byte encodes 1 to 6 bytes; thus, we need to ensure that we have enough space in the LinkedBuffer
        if (lb.writableBytes() < 6) {
            lb.discardSomeReadBytes();
        }
        char c = str.charAt(i);
        if (c < 0x80) {
            // 0xxxxxxx, one byte
            lb.writeByte((byte) c);
        } else if (c < 0x800) {
            // 110xxxxx 10xxxxxx, two bytes
            lb.writeByte(c >> 6 | 0xC0);
            lb.writeByte(c & 0x3F | 0x80);
        } else if (c < 0xd800 || (c >= 0xe000 && c < 0xfffe)) {
            // 1110xxxx 10xxxxxx 10xxxxxx, three bytes
            lb.writeByte(c >> 12 | 0xE0);
            lb.writeByte(c >> 6 & 0x3F | 0x80);
            lb.writeByte(c & 0x3F | 0x80);

        } else if (c >= 0xd800 && c < 0xdc00) {
            // 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx, four bytes
            int b2 = str.charAt(++i);
            if (b2 < 0xdc00 || b2 > 0xdfff) {
                throw new UTFDataFormatException("Invalid UTF-8 trailing-surrogate");
            }
            lb.writeByte(c >> 18 | 0xF0);
            lb.writeByte(c >> 12 & 0x3F | 0x80);
            lb.writeByte(c >> 6 & 0x3F | 0x80);
            lb.writeByte(c & 0x3F | 0x80);
        } else {
            // 111110xx 10xxxxxx 10xxxxxx 10xxxxxx 10xxxxxx, five bytes
            throw new UnsupportedOperationException("Not implemented yet");
        }
    }
    // return the LinkedBuffer, filled with the encoded string
    return lb;
}

public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    // Handle null input
    if (str == null) {
        return lb;
    }

    // Write the length of the string
    lb.putInt(str.length());

    // Write the string data
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // Handle non-ascii characters
        if (c > 127) {
            lb.putByte((byte) (c >>> 8));
        }
        lb.putByte((byte) c);
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check if the input string is null or empty
    if (str == null || str.length() == 0) {
        return lb;
    }

    // The number of bytes to be written
    int numBytes = 0;

    // The number of characters to be written
    int numChars = str.length();

    // The current character being written
    char currChar = 0;

    // The current byte being written
    byte currByte = 0;

    // The offset of the first byte to be written
    int startByteOffset = lb.position();

    // The offset of the last byte to be written
    int endByteOffset = startByteOffset;

    // Iterate through each character in the string
    for (int i = 0; i < numChars; i++) {
        // Get the current character
        currChar = str.charAt(i);

        // Check if the current character is a valid UTF8 character
        if (currChar < 0x80) {
            // The current character is a single byte value
            currByte = (byte) currChar;
            numBytes += 1;
        } else if (currChar < 0x800) {
            // The current character requires two bytes to encode
            numBytes += 2;
        } else if (currChar < 0xD800 || currChar > 0xDFFF) {
            // The current character requires three bytes to encode
            numBytes += 3;
        } else {
            // The current character requires four bytes to encode
            numBytes += 4;
        }
    }

    // Check if the buffer has enough capacity to write the bytes
    if (lb.remaining() < numBytes) {
        // The buffer does not have enough capacity, return the current state
        return lb;
    }

    // Reset the buffer's position and limit
    lb.position(0);
    lb.limit(numBytes);

    // Iterate through each character in the string again
    for (int i = 0; i < numChars; i++) {
        // Get the current character
        currChar = str.charAt(i);

        // Check if the current character is a valid UTF8 character
        if (currChar < 0x80) {
            // The current character is a single byte value
            currByte = (byte) currChar;
            lb.put(currByte);

        } else if (currChar < 0x800) {
            // The current character requires two bytes to encode
            lb.put((byte) (0xC0 | (currChar >> 6)));
            lb.put((byte) (0x80 | (currChar & 0x3F)));

        } else if (currChar < 0xD800 || currChar > 0xDFFF) {
            // The current character requires three bytes to encode
            lb.put((byte) (0xE0 | (currChar >> 12)));
            lb.put((byte) (0x80 | ((currChar >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (currChar & 0x3F)));

        } else {
            // The current character is a surrogate pair
            // Get the next character, which must be a surrogate
            currChar = str.charAt(++i);
            int codePoint = Character.toCodePoint(currChar, str.charAt(++i));

            // Write the surrogate pair to the buffer
            lb.put((byte) (0xF0 | (codePoint >> 18)));
            lb.put((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
            lb.put((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (codePoint & 0x3F)));
        }
    }

    // Reset the buffer's position and limit
    lb.position(startByteOffset);
    lb.limit(endByteOffset + numBytes);

    // Return the extended buffer
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, LinkedBuffer lb) {
    Charset utf8 = StandardCharsets.UTF_8;
    ByteBuffer buf = utf8.encode(CharBuffer.wrap(str));
    ByteBuffer lastBuf = lb.buffer();

    while (buf.hasRemaining()) {
        if (!lastBuf.hasRemaining()) {
            lastBuf = session.allocate(1024);
        }
        lastBuf.put(buf);
    }

    return lb;
}

