public static String findAndSubst(String key, Properties props) throws IllegalArgumentException {
    if (key == null) {
        throw new IllegalArgumentException("key cannot be null");
    }
    if (props == null) {
        throw new IllegalArgumentException("props cannot be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    Matcher matcher = Pattern.compile("\\$\\{([^}]+)\\}").matcher(value);
    while (matcher.find()) {
        String placeholder = matcher.group(1);
        String replacement = props.getProperty(placeholder);
        value = value.replace("${" + placeholder + "}", replacement == null ? "" : replacement);
    }
    return value;
}

