protected void appendDetail(StringBuffer buffer, String fieldName, int[] array) {
    // Check if the array is not null
    if (array != null) {
        // Append the field name to the buffer
        buffer.append(fieldName);
        // Append the opening square bracket to the buffer
        buffer.append('[');
        // Iterate over the array elements
        int i = 0;
        for (int element : array) {
            // Append the current element to the buffer
            buffer.append(element);
            // Check if there are more elements
            if (i < array.length - 1) {
                // Append the comma separator to the buffer
                buffer.append(',');
            }
            // Increment the index
            i++;
        }
        // Append the closing square bracket to the buffer
        buffer.append(']');
    } else {
        // If the array is null, append the {@code null} text to the buffer
        buffer.append("null");
    }
}

