public static List<PathSegment> decodePath(URI u, boolean decode) {
    List<PathSegment> segments = new ArrayList<>();
    String path = u.getRawPath();
    if (path == null) {
        return segments;
    }
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    for (String segment : path.split("/")) {
        segment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;
        segments.add(new PathSegmentImpl(segment));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Validate input
    if (u == null) {
        throw new IllegalArgumentException("u cannot be null");
    }

    // Initialize result list
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Get path component of URI and decode it if needed
    String path = u.getPath();
    if (decode) {
        path = decodePath(path);
    }

    // Split path into segments and add them to list
    String[] segments = path.split("/");
    for (String segment : segments) {
        if (!segment.isEmpty()) {
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Check the input parameters
    if (u == null) {
        throw new IllegalArgumentException("u must not be null");
    }

    // Get the path component of the URI
    String path = u.getPath();
    if (path == null) {
        return Collections.emptyList();
    }

    // Strip the leading '/' if necessary
    if (!path.isEmpty() && path.charAt(0) == '/') {
        path = path.substring(1);
    }

    // Split the path into segments
    String[] segments = path.split("/");

    // Create a new list to store the path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<>(segments.length);

    // Decode the path segments if necessary
    if (decode) {
        for (int i = 0; i < segments.length; i++) {
            try {
                segments[i] = URLDecoder.decode(segments[i].replace("+", "%2B"), "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new IllegalStateException(e);
            }
        }
    }

    // Add the path segments to the list
    for (String segment : segments) {
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) {
            throw new IllegalArgumentException("The URI must not be null");
        }

        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getRawPath();
        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        if (path.charAt(0) == '/') {
            path = path.substring(1);
        }

        for (String segment : path.split("/")) {
            if (decode) {
                segment = UriUtils.decode(segment, Charset.forName("UTF-8"));
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        // Check if the URI is null
        if (u == null) {
            throw new IllegalArgumentException("URI cannot be null");
        }

        // Check if the path component is null
        if (u.getPath() == null) {
            throw new IllegalArgumentException("Path component cannot be null");
        }

        // Create a new list to store the path segments
        List<PathSegmentImpl> pathSegments = new ArrayList<>();

        // Split the path component into individual path segments
        String[] pathComponents = u.getPath().split("/");

        // Check if the path component is an absolute path
        boolean isAbsolutePath = u.getPath().startsWith("/");

        // Add each path component to the list
        for (String pathComponent : pathComponents) {
            // Decode the path component if necessary
            if (decode) {
                pathComponent = URLDecoder.decode(pathComponent, "UTF-8");
            }

            // Add the path segment to the list
            pathSegments.add(new PathSegmentImpl(pathComponent, isAbsolutePath));

            // Reset the flag if the path component is an absolute path
            isAbsolutePath = false;
        }

        // Return the list of path segments
        return pathSegments;
    }

