public Converter lookup(Class<?> clazz) {
    // Step 1: Get the registered Converter for the specified class
    Converter converter = converters.get(clazz);

    // Step 2: Return the registered Converter if it exists
    if (converter != null) {
        return converter;
    }

    // Step 3: If no registered Converter exists, try to find a
    // converter for the superclass of the specified class
    Class<?> superclass = clazz.getSuperclass();
    if (superclass != null) {
        return lookup(superclass);
    }

    // Step 4: If no registered Converter exists for the superclass,
    // try to find a converter for the interfaces implemented by the
    // specified class
    Class<?>[] interfaces = clazz.getInterfaces();
    for (Class<?> anInterface : interfaces) {
        converter = lookup(anInterface);
        if (converter != null) {
            return converter;
        }
    }

    // Step 5: If no registered Converter exists for the superclass or
    // any of the interfaces implemented by the specified class, return
    // <code>null</code>
    return null;
}

