}

public Converter lookup(final Class<?> clazz) {
    // 1. Get the registered Converters from the registry by using the 'getRegisteredConverters' method
    //    and convert the resulting Stream to a List
    List<Converter> registeredConverters = ConverterRegistry.getRegisteredConverters().collect(Collectors.toList());

    // 2. Iterate over the List of registered Converters and check if any of them can convert the input class
    for (Converter converter : registeredConverters) {
        if (converter.canConvert(clazz)) {
            // 3. The first Converter that can convert the input class is returned
            return converter;
        }
    }

    // 4. If no Converter can convert the input class, return null
    return null;
}

private static long readRawVarint64() throws IOException {
    long result = 0;
    for (int shift = 0; shift < 64; shift += 7) {
        long b = inputStream.read();
        if (b == -1) {
            throw new EOFException("Unable to read varint, end of stream");
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    // HANDLE UNREACHABLE CODE REACHED
}

private static long readRawVarint64(InputStream in) throws IOException {
    int shift = 0;
    long result = 0;
    while (shift < 64) {
        final byte b = (byte) in.read();
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    if (shift < 64 && (b & 0x40) == 0) {
        result &= ~(1L << shift);
    }
    return result;
}

public long readRawVarint64() throws IOException {
    int temp = 0;
    int res = 0;
    for (int i = 0; i < 64; i += 7) {
        int b = input.read();
        if (b == -1) {
            throw new IOException("EOF encountered while reading a raw varint.");
        }
        res |= (b & 0x7F) << i;
        temp = (b >> 7);
        if (temp == 0) {
            return res;
        }
    }
    throw new IOException("There are too many bytes in the varint.");
}

public long readRawVarint64() throws IOException {
    // Read a single byte from the stream and store it in the buffer
    byteBuffer.put(inputStream.read());

    // Check if the byte is not the start of a long value
    if ((byteBuffer.get(byteBuffer.position() - 1) & 0x80) == 0) {
        // The byte value is a 64-bit value
        return Additional.decodeZigZag64(getLong(1));
    }

    // The byte value is the start of a long value
    long result = 0;
    int loop_counter = getLongLength(1);
    while (loop_counter > 0) {
        loop_counter--;
        // Read a byte from the stream and store it in the buffer
        byteBuffer.put(inputStream.read());

        result |= 0x7FL & (long) getInteger(1) << (loop_counter * 7);
    }

    return Additional.decodeZigZag64(result);
}

public long readRawVarint64() throws IOException {
    // Check if there is enough data in the buffer to read the full Varint
    if (isEndOfBuffer()) {
        return -1;
    }

    // Read the varint start (8 or 16 bits)
    int b = readRawByte();
    if (b == -1) {
        return -1;
    }

    // Check if we have a zero-valued varint (special case)
    if (b == 0) {
        return 0;
    }

    // Update the buffer number of bytes read
    setBufferNumberOfBytesRead(1);

    // Read the varint bytes
    int value = b & 0x7f;
    if (value < 128) {
        // One byte varint
        return value;
    }

    // Read the first byte of a two-byte varint
    int b2 = readRawByte();
    if (b2 == -1) {
        return -1;
    }

    // Update the buffer number of bytes read
    setBufferNumberOfBytesRead(2);

    // Check the continuation bit
    if (b2 < 0) {
        // Invalid varint
        return -1;
    }

    // Read the second byte of a two-byte varint
    int value2 = b2 & 0x7f;
    if (value2 < 128) {
        // Two bytes varint
        return (value << 8) | value2;
    }

    // Read the first byte of a four-byte varint
    int b3 = readRawByte();
    if (b3 == -1) {
        return -1;
    }

    // Update the buffer number of bytes read
    setBufferNumberOfBytesRead(3);

    // Check the continuation bit
    if (b3 < 0) {
        // Invalid varint
        return -1;
    }

    // Read the second byte of a four-byte varint
    int value3 = b3 & 0x7f;
    if (value3 < 128) {
        // Three bytes varint
        return (value << 16) | (value2 << 8) | value3;
    }

    // Read the first byte of a five-byte varint
    int b4 = readRawByte();
    if (b4 == -1) {
        return -1;
    }

    // Update the buffer number of bytes read
    setBufferNumberOfBytesRead(4);

    // Check the continuation bit
    if (b4 < 0) {
        // Invalid varint
        return -1;
    }

    // Read the third byte of a five-byte varint
    int value4 = b4 & 0x7f;
    if (value4 < 128) {
        // Four bytes varint
        return (value << 24) | (value2 << 16) | (value3 << 8) | value4;
    }

    // Read the first byte of a six-byte varint
    int b5 = readRawByte();
    if (b5 == -1) {
        return -1;
    }

    // Update the buffer number of bytes read
    setBufferNumberOfBytesRead(5);

    // Check the continuation bit
    if (b5 < 0) {
        // Invalid varint
        return -1;
    }

    // Read the fourth byte of a six-byte varint
    int value5 = b5 & 0x7f;
    if (value5 < 128) {
        // Five bytes varint
        return (value << 32) | (value2 << 24) | (value3 << 16) | (value4 << 8) | value5;
    }

    // Read the fifth byte of a six-byte varint
    int b6 = readRawByte();
    if (b6 == -1) {
        return -1;
    }

    // Update the buffer number of bytes read
    setBufferNumberOfBytesRead(6);

    // Check the continuation bit
    if (b6 < 0) {
        // Invalid varint
        return -1;
    }

    // Read the sixth byte of a six-byte varint
    int value6 = b6 & 0x7f;
    if (value6 < 128) {
        // Five bytes varint
        return (value << 40) | (value2 << 32) | (value3 << 24) | (value4 << 16) | (value5 << 8) | value6;
    }

    // Cannot parse varint longer than 6 bytes
    return -1;
}

