void pop(String descriptor) {
    // Handle invalid input
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }

    // Parse the descriptor to get the number of types to pop
    Type[] types;
    try {
        types = Type.getArgumentTypes(descriptor);
    } catch (Exception e) {
        throw new RuntimeException("Error parsing descriptor", e);
    }

    // Pop each type from the output frame stack
    for (int i = 0; i < types.length; i++) {
        Type t = types[i];
        if (t.getSize() > 0) {
            // Pop the value from the output frame stack
            Object value = getOutputFrame().pop();

            // Check if the popped value is of the correct type, and throw an exception if it is not
            if (!value.getClass().isAssignableFrom(t.getClazz())) {
                throw new IllegalStateException("Expected value of type " + t + ", but found " + value);
            }
        }
    }
}

public void pop(String descriptor){
    if(descriptor == null){
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int numParams = Type.getType(descriptor).getArgumentTypes().length;
    for(int i = 0; i < numParams; i++){
        outputFrameStack.pop();
    }
}

void pop(String descriptor) {
    // Check if the descriptor is a valid type descriptor
    if (!DescriptorUtils.isValidTypeDescriptor(descriptor)) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    // Get the type of the descriptor
    Type type = DescriptorUtils.getTypeFromDescriptor(descriptor);

    // Check if the type is an array type
    if (type.getSort() == Type.ARRAY) {
        // Pop the array elements
        for (int i = 0; i < type.getDimensions(); i++) {
            Object element = getCurrentFrame().pop();
            if (element == null) {
                throw new InternalError("Null array element");
            }
        }

        // Leave an array reference on the stack
        getCurrentFrame().push(type);
    } else {
        // Pop a single value of the given type
        Object value = getCurrentFrame().pop(type);
        if (value == null) {
            throw new InternalError("Null value");
        }
    }
}

private void pop(String descriptor) {
    if (descriptor.startsWith(")")) {
        return;
    }

    int numArgs = 1;
    if (!descriptor.startsWith("(")) {
        descriptor = "(" + descriptor;
    }

    int topIndex = stack.size() - 1;
    while (descriptor.charAt(0) != ')') {
        Type type = Type.getType(descriptor);
        stack.remove(topIndex - numArgs);
        numArgs++;
        descriptor = descriptor.substring(1);
    }
}

public Object pop(String descriptor) {
        Type type = Type.getType(descriptor);
        if (type.getSort() == Type.ARRAY) {
            int dims = type.getDimensions();
            Object[] array = new Object[dims];
            for (int i = 0; i < dims; i++) {
                array[i] = stack.pop();
            }
            return array;
        }
        if (type.getSort() == Type.OBJECT || type.getSort() == Type.METHOD) {
            Object[] args = new Object[type.getArgumentTypes().length];
            for (int i = 0; i < type.getArgumentTypes().length; i++) {
                args[i] = stack.pop();
            }
            return args;
        }
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

public void write(byte[] b, int off, int len) throws IOException {
    // Check for null array
    if (b == null) {
        throw new NullPointerException("Byte array is null");
    }

    // Check for valid arguments
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid arguments: off=" + off + ", len=" + len + ", b.length=" + b.length);
    }

    // Write the bytes to the output stream
    for (int i = off; i < off + len; i++) {
        write(b[i]);
    }
}

public void write(byte[] b, int off, int len) throws IOException {
    if (len < 0) {
        throw new IndexOutOfBoundsException("len is negative: " + len);
    }

    if (off < 0 || off > b.length || len > b.length - off) {
        throw new IndexOutOfBoundsException("off is invalid: " + off + " or len is invalid: " + len);
    }

    for (int i = off; i < off + len; i++) {
        out.write(b[i]);
    }
}

public void write(final byte[] b, final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Cannot write a null byte array");
    } else if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid offset and length for byte array");
    } else if (len == 0) {
        return;
    }

    for (int i = 0; i < len; i++) {
        this.buffer[this.position++] = b[off + i];
    }
}

public void write(byte[] b, int off, int len) throws IOException {

    // Check that the offset and length are valid
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException();
    }

    // Write the bytes to the buffer
    int remaining = len;
    while (remaining > 0) {
        int written = Math.min(remaining, buffer.length - position);
        System.arraycopy(b, off, buffer, position, written);
        off += written;
        remaining -= written;
        position += written;

        // If the buffer is full, flush it to the underlying stream
        if (position == buffer.length) {
            flush();
        }
    }
}

public void write(byte[] b, int off, int len) throws IOException {
    // Step 1: Validate input parameters
    if (b == null) {
        throw new NullPointerException("b");
    } else if (off < 0 || len < 0 || (off + len) > b.length) {
        throw new IndexOutOfBoundsException("off or len out of bounds");
    }

    // Step 2: Write the bytes to the output stream
    for (int i = 0; i < len; i++) {
        out.write(b[off + i]);
    }
}

