protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the edge is already in the index
    if (this.index.containsKey(sourceVertex)) {
        // The source vertex is already in the index, add the target vertex to the list of edges
        List<E> edges = this.index.get(sourceVertex);
        edges.add(e);
    } else {
        // The source vertex is not in the index, create a new list of edges for it
        List<E> edges = new ArrayList<>();
        edges.add(e);
        this.index.put(sourceVertex, edges);
    }

    // Check if the reversed edge is already in the index
    if (this.index.containsKey(targetVertex)) {
        // The target vertex is already in the index, add the source vertex to the list of edges
        List<E> edges = this.index.get(targetVertex);
        edges.add(e);
    } else {
        // The target vertex is not in the index, create a new list of edges for it 
        List<E> edges = new ArrayList<>();
        edges.add(e);
        this.index.put(targetVertex, edges);
    }
}

public void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the input is valid
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Get the corresponding linked lists for the source and target vertices
    LinkedList<E> sourceList = vertexToEdgesMap.get(sourceVertex);
    LinkedList<E> targetList = vertexToEdgesMap.get(targetVertex);

    // Check if the source and target vertices are not already connected
    if (sourceList.contains(e) || targetList.contains(e)) {
        throw new IllegalStateException("Vertices are already connected");
    }

    // Add the edge to the index
    sourceList.add(e);
    targetList.add(e);
}

public void addToIndex(V sourceVertex, V targetVertex, E e) {
    // check if the edge already exists in the index
    if (!edgeMap.containsKey(sourceVertex)) {
        // if not, create a new list for the source vertex
        edgeMap.put(sourceVertex, new ArrayList<>());
    }
    // add the edge to the list of edges for the source vertex
    edgeMap.get(sourceVertex).add(e);
    // if the target vertex is not already in the index, add it
    if (!edgeMap.containsKey(targetVertex)) {
        edgeMap.put(targetVertex, new ArrayList<>());
    }
    // add the edge to the list of edges for the target vertex
    edgeMap.get(targetVertex).add(e);
}

public void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the edge is null
    if (e == null) {
        throw new IllegalArgumentException("Edge cannot be null");
    }

    // Get the source and target vertices
    V source = sourceVertex;
    V target = targetVertex;

    // Check if the source and target vertices are null
    if (source == null || target == null) {
        throw new IllegalArgumentException("Source or target vertex cannot be null");
    }

    // Check if the source and target vertices exist in the graph
    if (!this.containsVertex(source) || !this.containsVertex(target)) {
        throw new IllegalArgumentException("Source or target vertex does not exist in the graph");
    }

    // Add the edge to the index
    this.index.put(e, Pair.of(source, target));

    // Add the edge to the adjacency list of the source vertex
    if (!this.adjacencyList.containsKey(source)) {
        this.adjacencyList.put(source, new HashSet<>());
    }
    this.adjacencyList.get(source).add(target);

    // Add the edge to the adjacency list of the target vertex
    if (!this.adjacencyList.containsKey(target)) {
        this.adjacencyList.put(target, new HashSet<>());
    }
    this.adjacencyList.get(target).add(source);
}

