public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the x coordinate of the center of the box
    double centerX = box.getX() + (box.getWidth() / 2.0);

    // Calculate the width of each resulting box
    double halfWidth = box.getWidth() / 2.0;

    // Create two new boxes with the calculated dimensions
    Box2D firstBox = new Box2D(box.getX(), box.getY(), centerX - halfWidth, box.getHeight());
    Box2D secondBox = new Box2D(centerX + halfWidth, box.getY(), box.getX() + box.getWidth(), box.getHeight());

    // Return a pair with the two resulting boxes
    return new Pair<>(firstBox, secondBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Throw exception if input is null or not a 2D box
    if (box == null || !box.is2D()) {
        throw new IllegalArgumentException("Box must be a 2D box");
    }

    // Calculate the center of the box
    double centerX = box.getX() + box.getWidth() / 2;
    double centerY = box.getY() + box.getHeight() / 2;

    // Create two new boxes with half the width of the original box
    Box2D box1 = new Box2D(box.getX(), box.getY(), box.getWidth() / 2, box.getHeight());
    Box2D box2 = new Box2D(centerX, centerY, box.getWidth() / 2, box.getHeight());

    // Return a pair of the two resulting boxes
    return Pair.of(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Check if the box is valid
    if (box == null || box.getWidth() <= 0) {
        throw new IllegalArgumentException("Invalid box");
    }

    // Calculate the half width of the box
    double halfWidth = box.getWidth() / 2;

    // Create a new box for the first half along the x axis
    Box2D firstHalf = new Box2D(box.getCenter().getX() - halfWidth, box.getCenter().getY(), halfWidth, box.getHeight());

    // Create a new box for the second half along the x axis
    Box2D secondHalf = new Box2D(box.getCenter().getX() + halfWidth, box.getCenter().getY(), halfWidth, box.getHeight());

    // Return a pair with the two resulting boxes
    return new Pair<>(firstHalf, secondHalf);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Invalid input: box cannot be null");
    }

    // Calculate the midpoint of the x-axis
    Vec2D xMidpoint = new Vec2D(box.getX() + (box.getWidth() / 2), box.getY());

    // Create two new boxes, one on each side of the midpoint
    Box2D leftBox = new Box2D(box.getX(), box.getY(), xMidpoint.getX(), box.getHeight());
    Box2D rightBox = new Box2D(xMidpoint.getX(), box.getY(), box.getX() + box.getWidth(), box.getHeight());

    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint of the box along the x-axis
    double midX = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2.0;

    // Create two new boxes, one with the points on the left of the midpoint
    // and the other with the points on the right of the midpoint
    Box2D leftBox = new Box2D(box.getMinX(), midX, box.getMaxX(), box.getMaxY());
    Box2D rightBox = new Box2D(midX, box.getMinY(), box.getMaxX(), box.getMaxY());

    // Return a pair containing the two resulting boxes
    return new Pair<>(leftBox, rightBox);
}

public void enlarge(int size) {
    // Check for invalid inputs
    if (size < 0) {
        throw new IllegalArgumentException("Invalid input: size must be non-negative.");
    }

    // Calculate the new capacity needed
    int newCapacity = this.capacity + size;

    // If the array is already large enough, return
    if (newCapacity <= this.capacity) {
        return;
    }

    // Create a new array with the appropriate capacity
    byte[] newArray = new byte[newCapacity];

    // Copy the old array into the new array
    System.arraycopy(this.array, 0, newArray, 0, this.capacity);

    // Update the field variable to the new array
    this.array = newArray;
}

private void enlarge(final int size) {
    // Check if the requested size is negative
    if (size < 0) {
        throw new IllegalArgumentException("Negative size specified");
    }

    // Calculate the new capacity for the byte vector
    final int newCapacity = this.capacity + size;

    // Create a new byte array with the new capacity
    final byte[] newBytes = new byte[newCapacity];

    // Copy the existing bytes into the new byte array
    System.arraycopy(this.bytes, 0, newBytes, 0, this.size());

    // Replace the old byte array with the new one
    this.bytes = newBytes;

    // Update the capacity
    this.capacity = newCapacity;
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return;
    }
    int oldCapacity = data.length;
    int newCapacity = oldCapacity + size;
    byte[] oldData = data;
    data = new byte[newCapacity];
    System.arraycopy(oldData, 0, data, 0, oldData.length);
    size += oldData.length - 1;
}

private void enlarge(final int size) {
    // Check if the new size is greater than the current capacity. If so, double the capacity.
    if (size > this.capacity) {
        int newCapacity = (this.capacity == 0) ? 1 : this.capacity;
        while (newCapacity < size) {
            newCapacity = newCapacity * 2;
        }
        this.bytes = Arrays.copyOf(this.bytes, newCapacity);
        this.capacity = newCapacity;
    }
}

private void enlarge(final int size) {
    // Check if the new size is positive
    if (size < 0) {
        throw new IllegalArgumentException("Size must be positive");
    }

    // Check if the byte vector already has enough capacity
    if (size <= bytes.length) {
        return;
    }

    // Create a new byte array with the desired size
    byte[] newBytes = new byte[size];

    // Copy the elements from the old array to the new array
    System.arraycopy(bytes, 0, newBytes, 0, bytes.length);

    // Update the bytes field with the new array
    bytes = newBytes;
}

