public static String decapitalize(String name) {
    // Step 1: Check if the input name is null or empty
    if (name == null || name.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: Name cannot be null or empty");
    }

    // Step 2: Split the name into an array of words
    String[] words = name.split(" ");

    // Step 3: Iterate over each word and capitalize the first letter
    for (int i = 0; i < words.length; i++) {
        words[i] = words[i].substring(0, 1).toLowerCase() + words[i].substring(1);
    }

    // Step 4: Join the capitalized words back into a single string
    String capitalizedName = String.join(" ", words);

    return capitalizedName;
}

public static String capitialize(String name) {
    // Step 1: Check if the input is null or empty
    if (name == null || name.isEmpty()) {
        throw new IllegalArgumentException("Name cannot be null or empty");
    }
    // Step 2: Convert the first character to uppercase
    name = name.substring(0, 1).toUpperCase() + name.substring(1);
    return name;
}

public static String capitalize(String name) {
    // Validate input
    if (name == null) {
        throw new IllegalArgumentException("Name cannot be null");
    }

    // Handle edge case
    if (name.isEmpty()) {
        return name;
    }

    // Reverse the name
    char[] chars = name.toCharArray();
    for (int i = 0; i < chars.length / 2; i++) {
        char temp = chars[i];
        chars[i] = chars[chars.length - i - 1];
        chars[chars.length - i - 1] = temp;
    }

    // Return the reversed name
    return new String(chars);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        totalSize += out.write(node.getBuffer(), node.getOffset(), node.getLength());
        node = node.getNext();
    }
    return totalSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalContentSize = 0;
    while (node != null) {
        out.write(node.getContent());
        totalContentSize += node.getContent().length;
        node = node.getNext();
    }
    return totalContentSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Check for null input
    if (out == null || node == null) {
        throw new IllegalArgumentException("Invalid input: out or node cannot be null");
    }

    // Write the buffer size
    int bufferSize = node.bufferSize();
    out.writeInt(bufferSize);

    // Write the buffer data
    for (Data data : node.data) {
        out.writeInt(data.length);
        out.write(data.bytes, data.offset, data.length);
    }

    // Return the total content size
    return bufferSize;
}

