public static Supplier<String> createStringSupplier(int start) {
    return () -> "String-" + start++;
}

private static Supplier<String> createStringSupplier(int start) {
    /*
     * Get a new combined stream that goes over every possible sequence from start to Integer.MAX_VALUE.
     * The sequence consists of every combinations of every character in characters.
     * This is done using the powerset algorithm.
     */
    Stream<String> stream = IntStream.range(start, Integer.MAX_VALUE)
            .mapToObj(i -> String.valueOf(i))
            .flatMap(s -> IntStream.rangeClosed('a', 'z')
                    .mapToObj(i -> (char) i)
                    .map(c -> s + c)
            );
    return () -> stream
            //filter out duplicates
            .distinct()
            //map to String
            .map(String::new)
            //Note: there is no need to close the stream, since it is not an AutoCloseable
            //but return the first element, which is the generated String
            .findFirst()
            .orElseThrow(() -> new IllegalStateException("No more unique Strings available"));
}

