public String format(final LoggingEvent event) {

// Check if the event is null
if (event == null) {
throw new IllegalArgumentException("Event cannot be null");
}

// Format the event using the built-in method
String logLine = event.getMessage();

// Check if the log line is null or empty
if (logLine == null || logLine.isEmpty()) {
return "";
}

// Replace any tags in the log line
Pattern tagPattern = Pattern.compile("\\{.*?\\}");
Matcher tagMatcher = tagPattern.matcher(logLine);
while (tagMatcher.find()) {
String tag = tagMatcher.group();
tag = tag.replaceAll("\\{", "");
tag = tag.replaceAll("}", "");
logLine = logLine.replace(tag, event.getProperty(tag));
}

// Replace any placeholders in the log line
Pattern placeholderPattern = Pattern.compile("\\$\\{.*?\\}");
Matcher placeholderMatcher = placeholderPattern.matcher(logLine);
while (placeholderMatcher.find()) {
String placeholder = placeholderMatcher.group();
placeholder = placeholder.replaceAll("\\$\\{", "");
placeholder = placeholder.replaceAll("}", "");
logLine = logLine.replace(placeholder, event.getProperty(placeholder));
}

// Return the formatted log line
return logLine;
}

