    for (int i = start; i < end; i++) {
        // Get the type of the current frame
        FrameType type = currentFrame[i];

        // If the type is a reference type, write a tag and a value offset to the StackMapTable
        if (type.isReference()) {
            stackMapTableEntries.writeByte(type.getStackMapTag());
            stackMapTableEntries.writeShort(type.getOffset());
        }

        // If the type is a double or a long type, write two tag and two value offsets to the StackMapTable
        else if (type.isWide()) {
            stackMapTableEntries.writeByte(Opcodes.ITEM_Wide);
            stackMapTableEntries.writeShort(type.getOffset());
            stackMapTableEntries.writeByte(type.getSecondaryTag());
            stackMapTableEntries.writeShort(type.getSecondaryOffset());
        }
