public static int nextPrime(int desiredCapacity) {
    // Check if the desiredCapacity is already prime
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // Find the next prime number greater than the desiredCapacity
    int nextPrime = desiredCapacity + 1;
    while (!isPrime(nextPrime)) {
        nextPrime++;
    }

    // If the desiredCapacity is less than 1000, check if the next prime is within 11% of the desiredCapacity
    if (desiredCapacity < 1000 && Math.abs(desiredCapacity - nextPrime) / desiredCapacity > 0.11) {
        // If not, find the next prime number that is within 11% of the desiredCapacity
        int diff = (int) Math.ceil(desiredCapacity * 0.11);
        while (Math.abs(desiredCapacity - nextPrime) > diff) {
            nextPrime++;
        }
    }
    return nextPrime;
}

public static int nextPrime(int desiredCapacity) {
    // Check if the desiredCapacity is less than 11
    if (desiredCapacity < 11) {
        // If so, return 11
        return 11;
    }

    // Check if the desiredCapacity is less than 1000
    if (desiredCapacity < 1000) {
        // If so, return desiredCapacity * 1.1
        return (int) Math.round(desiredCapacity * 1.1);
    }

    // Check if the desiredCapacity is less than 10000
    if (desiredCapacity < 10000) {
        // If so, return desiredCapacity * 1.2
        return (int) Math.round(desiredCapacity * 1.2);
    }

    // If the desiredCapacity is greater than 10000, return desiredCapacity * 1.25
    return (int) Math.round(desiredCapacity * 1.25);
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Invalid input: desiredCapacity must be non-negative");
    }
    if (desiredCapacity >= 1000) {
        desiredCapacity = (int) (desiredCapacity * 0.91);
    } else {
        desiredCapacity = (int) (desiredCapacity * 0.95);
    }
    for (int i = desiredCapacity; i < Integer.MAX_VALUE; i++) {
        if (isPrime(i)) {
            return i;
        }
    }
    return -1;
}

public static int nextPrime(int desiredCapacity) {

    if (desiredCapacity <= 0) {
      throw new IllegalArgumentException("desiredCapacity must be a positive integer");
    }

    // if the desired capacity is already prime, return it
    if (isPrime(desiredCapacity)) {
      return desiredCapacity;
    }

    // find the closest prime number which is greater than the desired capacity
    int closestPrime = -1;
    for (int i = desiredCapacity + 1; i < Integer.MAX_VALUE; i++) {
      if (isPrime(i)) {
        closestPrime = i;
        break;
      }
    }

    // if no prime number was found, return Integer.MAX_VALUE
    if (closestPrime == -1) {
      return Integer.MAX_VALUE;
    }

    // return the closest prime number with a tolerance of 11%
    if (closestPrime - desiredCapacity < 0.11 * desiredCapacity) {
      return closestPrime;
    }

    return desiredCapacity;
  }

public static int getNextPrime(int desiredCapacity) {
    // Handle invalid inputs
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("Desired capacity cannot be negative");
    }

    // Start with the closest prime number above the desired capacity
    int prime = getNextPrimeAbove(desiredCapacity);

    // If the prime is too close to the desired capacity, find the next prime number
    if (Math.abs(desiredCapacity - prime) <= 1) {
      prime = getNextPrimeAbove(prime);
    }

    return prime;
  }

  private static int getNextPrimeAbove(int n) {
    // Handle invalid inputs
    if (n < 0) {
      throw new IllegalArgumentException("Invalid input");
    }

    // Start with the next prime number above n
    n++;
    while (!isPrime(n)) {
      n++;
    }
    return n;
  }

  private static boolean isPrime(int n) {
    // Handle invalid inputs
    if (n < 2) {
      return false;
    }

    // Loop through the numbers from 2 to the square root of n
    for (int i = 2; i <= Math.sqrt(n); i++) {
      if (n % i == 0) {
        return false;
      }
    }
    return true;
  }

