public static String trimTrailingWhitespace(String str) {
    int length = str.length();
    for (int i = length - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            return str.substring(0, i + 1);
        }
    }
    return "";
}

public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        return null;
    }
    int length = str.length();
    int start = 0;
    while (start < length && Character.isWhitespace(str.charAt(start))) {
        start++;
    }
    if (start == 0) {
        return str;
    }
    if (start == length) {
        return "";
    }
    return str.substring(start, length);
}

public static String trimTrailingWhitespace(String str) {
    // Check if the input String is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }

    // Get the length of the String
    int length = str.length();

    // Get the last index of the String that is not whitespace
    int lastNonWhitespaceIndex = length - 1;
    for (int i = length - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            lastNonWhitespaceIndex = i;
            break;
        }
    }

    // Return a new String that is a substring of the input String, starting at 0 and ending at the last non-whitespace index
    return str.substring(0, lastNonWhitespaceIndex + 1);
}

public static String trimTrailingWhitespace(String str) {
    if (str == null || str.isEmpty()) {
        return str;
    }

    int index = str.length() - 1;
    while (index >= 0 && Character.isWhitespace(str.charAt(index))) {
        index--;
    }

    return str.substring(0, index + 1);
}

public static String trimTrailingWhitespace(String str) {
    // Find the last non-whitespace character
    int lastNonWhitespace = str.length() - 1;
    while (lastNonWhitespace >= 0 && Character.isWhitespace(str.charAt(lastNonWhitespace))) {
        lastNonWhitespace--;
    }
    // If the last character is not a whitespace character, return the original String
    if (lastNonWhitespace < str.length() - 1) {
        return str;
    }
    // Otherwise, return the substring up to the last non-whitespace character
    return str.substring(0, lastNonWhitespace + 1);
}

