public void init() {
    // Check the dist path for the config file
    File configFile = new File("dist/config.json");

    // If the file does not exist, create it and print a message
    if (!configFile.exists()) {
        try {
            configFile.createNewFile();
            System.out.println("Config file not found, creating a new one...");
        } catch (IOException e) {
            System.out.println("Error creating config file: " + e.getMessage());
        }
    }

    // Load the config file
    String configString = null;
    try {
        configString = new String(Files.readAllBytes(Paths.get("dist/config.json")));
    } catch (IOException e) {
        System.out.println("Error reading config file: " + e.getMessage());
    }

    // If the config string is null, return
    if (configString == null) {
        return;
    }

    // Parse the config string into a JSON object
    JSONObject configJson = new JSONObject(configString);

    // Check if the config JSON object is empty
    if (configJson.isEmpty()) {
        System.out.println("Config file is empty, please fill in the missing fields.");
        return;
    }

    // Get the dist path from the config JSON object
    String distPath = configJson.getString("dist_path");

    // If the dist path is not specified, print a message and return
    if (distPath == null || distPath.isEmpty()) {
        System.out.println("Please specify a valid dist path in the config file.");
        return;
    }

    // Get the output path from the config JSON object
    String outputPath = configJson.getString("output_path");

    // If the output path is not specified, print a message and return
    if (outputPath == null || outputPath.isEmpty()) {
        System.out.println("Please specify a valid output path in the config file.");
        return;
    }

    // Get the input path from the config JSON object
    String inputPath = configJson.getString("input_path");

    // If the input path is not specified, print a message and return
    if (inputPath == null || inputPath.isEmpty()) {
        System.out.println("Please specify a valid input path in the config file.");
        return;
    }

    // Set the dist path, output path, and input path
    String finalDistPath = distPath;
    String finalOutputPath = outputPath;
    String finalInputPath = inputPath;

    // Create a new thread for the config initialization
    Thread configInitThread = new Thread() {
        public void run() {
            try {
                // Initialize the config
                initializeConfig(finalDistPath, finalOutputPath, finalInputPath);
            } catch (IOException e) {
                System.out.println("Error initializing config: " + e.getMessage());
            }
        }
    };

    // Start the config initialization thread
    configInitThread.start();
}

