public byte[] toByteArray() {
    // Initialize an empty byte array
    byte[] bytes = new byte[0];

    // Iterate through each buffer in the buffer list
    for (ByteBuffer buffer : bufferList) {
        // Get the current buffer's limit
        int limit = buffer.limit();
        // Get the current buffer's position
        int position = buffer.position();

        // Calculate the number of bytes available to read
        int available = limit - position;

        // If there are no bytes available, skip to the next buffer
        if (available <= 0) {
            continue;
        }

        // Create a new byte array with the available number of bytes
        byte[] newBytes = new byte[available];

        // Get the bytes from the current buffer into the new byte array
        buffer.get(newBytes);

        // Add the new byte array to the overall byte array
        bytes = ArrayUtils.addAll(bytes, newBytes);
    }

    // Return the complete byte array
    return bytes;
}

