public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int sz = str.length();
    StringBuilder out = new StringBuilder(sz);
    for (int x=0; x<sz; x++) {
        char ch = str.charAt(x);
        if (ch == '\\') {
            char next = str.charAt(x+1);
            int t = 0;
            switch (next) {
                case 'b': t = '\b'; break;
                case 'f': t = '\f'; break;
                case 'n': t = '\n'; break;
                case 'r': t = '\r'; break;
                case 't': t = '\t'; break;
                case '\\': t = '\\'; break;
                case '"': t = '"'; break;
                default:
                    if (next >= '0' && next <= '7') {
    t = Integer.parseInt(str.substring(x+1, x+4), 8);
                        out.append((char) t);
                        x += 3;
                        continue;
                    }
            }
            if (t != 0) {
                out.append(t);
                x++;
                continue;
            }
        }
        out.append(ch);
    }
    return out.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    boolean escaped = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        // If the character is a backslash and it is not the last character,
        // and the next character is a valid escape sequence, then unescape the character.
        // Otherwise, append the character to the output string.
        if (c == '\\' && i < str.length() - 1 && isValidEscapeSequence(str.charAt(i + 1))) {
            escaped = true;
            i++;
        } else {
            escaped = false;
        }
        sb.append(c);
    }

    if (escaped) {
        return sb.toString();
    } else {
        return str;
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int current = 0;
    while (current < str.length()) {
        char c = str.charAt(current);
        if (c != '\\') {
            result.append(c);
            current++;
        } else {
            if (current == str.length() - 1) {
                throw new Exception("Invalid input");
            }
            c = str.charAt(current + 1);
            if (c == 'n') {
                result.append('\n');
            } else if (c == 't') {
                result.append('\t');
            } else if (c == 'r') {
                result.append('\r');
            } else if (c == 'f') {
                result.append('\f');
            } else if (c == '\'') {
                result.append('\'');
            } else if (c == '\"') {
                result.append('"');
            } else if (c == '\\') {
                result.append('\\');
            } else {
                throw new Exception("Invalid escape sequence");
            }
            current += 2;
        }
    }
    return result.toString();
}

