    int position = 0;
    while (position < str.length()) {
        char c = str.charAt(position);
        if (c == '\\') {
            position++;
            c = str.charAt(position);
            if (c == 'n') {
                result.append('\n');
            } else if (c == 't') {
                result.append('\t');
            } else {
                result.append(c);
            }
        } else {
            result.append(c);
        }
        position++;
    }

    return result.toString();
}

public static String unescapeJava(String str) throws Exception {
        if (str == null)
            return null;
        StringBuilder sb = new StringBuilder();
        int pos = 0;
        while (pos < str.length()) {
            char c = str.charAt(pos);
            if (c == '\\') {
                if (++pos == str.length())
                throw new Exception("Invalid input");
                c = str.charAt(pos);
                switch (c) {
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case '\'':
                    case '\\':
                    case '"':
                        sb.append(c);
                    default:
                        throw new Exception("Invalid input");
                }
            }
            else {
                if (c == '\\' && ++pos == str.length())
                    throw new Exception("Invalid input");
                else
                    sb.append(c);
            }
            pos++;
        }
        return sb.toString();
    }

