    if (charBuffer == null || charBuffer.length == 0) {
        throw new RuntimeException("Invalid or null char buffer provided");
    }

    final int length = readUnsignedShort(constantPoolEntryIndex);
    int offset = constantPoolEntryIndex + 2;
    if (offset + length > classFileBuffer.length) {
        throw new RuntimeException("String data is invalid or truncated");
    }

    return new String(classFileBuffer, offset, length);
}

Optional<String> readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
	try {
		ByteBuffer utfBuffer = getConstantPoolEntryRaw(constantPoolEntryIndex);
		// Check that the next byte matches the UTF8 magic number
		if (utfBuffer.get() != UTF8_BYTE_1 || utfBuffer.get() != UTF8_BYTE_2) {
			return Optional.empty();
		}
		// Read the UTF8 length
		final int stringLength = utfBuffer.getShort();
		// Compare the buffer size against the requested length
		if (charBuffer.length < stringLength) {
			// The buffer is too small, allocate a new one
			final char[] newBuffer = new char[stringLength];
			// Copy the content of the old buffer to the new buffer
			System.arraycopy(charBuffer, 0, newBuffer, 0, charBuffer.length);
			// Return the read string
			return Optional.of(new String(newBuffer, 0, stringLength));
		} else {
			// The buffer is large enough, directly read the string
			utfBuffer.get(charBuffer, charBuffer.length - stringLength, stringLength);
			return Optional.of(new String(charBuffer));
		}
	} catch (IOException exception) {
		return Optional.empty();
	}
}

