private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator from the start node with the specified direction
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Iterate over the nodes until a node that satisfies the predicate is found
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
    }

    // If the circulator did not find a node that satisfies the predicate, return the circulator to the stop node
    return new OuterFaceCirculator(stop, dir);
}

public OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate.test(stop)) {
        return new OuterFaceCirculator(stop, dir);
    }

    Node current = start;
    do {
        current = current.getNeighbor(dir);
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, dir);
        }
    } while (current != stop);

    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Edge case: If the start and stop nodes are the same, return a circulator to the stop node
    if (start == stop) {
        return new OuterFaceCirculator(stop);
    }

    // Edge case: If the start and stop nodes are not on the same face, return a circulator to the stop node
    if (start.getFace() != stop.getFace()) {
        return new OuterFaceCirculator(stop);
    }

    // Find the first node on the face of the start node that satisfies the predicate
    Node node = start;
    do {
        node = node.move(dir, 1);
    } while (!predicate.test(node) && node != stop);

    // Check if a node satisfying the predicate was found
    if (node == stop) {
        // If not, return a circulator to the stop node
        return new OuterFaceCirculator(stop);
    } else {
        // Otherwise, return a circulator to the found node
        return new OuterFaceCirculator(node);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Step 1: Initialize the circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);

    // Step 2: Set the direction and initiate the traversal
    circulator.setDirection(dir);

    // Step 3: Loop until we reach the stop node or find a node satisfying the predicate
    while (circulator.next() != stop) {
        if (predicate.test(circulator.current())) {
            // Step 4: Return the circulator if we find a node satisfying the predicate
            return circulator;
        }
    }

    // Step 5: Return the circulator to the stop node if we reach it
    return circulator;
}

