private static int compareSigned(long a, long b) {
    // Check for negative zero
    if (a == 0L && b == 0L) {
        return 0;
    }
    // Handle negative values
    else if (a < 0L && b < 0L) {
        // Check for overflow
        if (Math.abs(a) > Math.abs(b)) {
            return -1;
        } else if (Math.abs(a) < Math.abs(b)) {
            return 1;
        }
        // Handle equal values
        else {
            return 0;
        }
    }
    // Handle positive values
    else if (a > 0L && b > 0L) {
        // Check for overflow
        if (a > b) {
            return 1;
        } else if (a < b) {
            return -1;
        }
        // Handle equal values
        else {
            return 0;
        }
    }
    // Handle mixed sign values (negative + positive or positive + negative)
    else {
        if (a < 0L) {
            return -1;
        } else {
            return 1;
        }
    }
}

private static int compareSigned(long a, long b) {
    // Handle potential overflow
    if (a > 0) {
        if (b > 0) {
            // Both are positive
            return (int) (a - b);
        } else {
            // First is positive, second is negative
            return 1;
        }
    } else {
        if (b > 0) {
            // First is negative, second is positive
            return -1;
        } else {
            // Both are negative
            return (int) (b - a);
        }
    }
}

private static int compareSigned(long a, long b) {
    // Check for negative zero
    if (a == 0L && 1L / a == -1L) {
        a = -0L;
    }
    if (b == 0L && 1L / b == -1L) {
        b = -0L;
    }

    // Compare using unsigned longs
    long ua = a;
    long ub = b;
    int result = Long.compareUnsigned(ua, ub);

    // If the result is zero, compare signs
    if (result == 0) {
        int asign = (int) (a >> 63);
        int bsign = (int) (b >> 63);
        if (asign < bsign) {
            result = -1;
        } else if (asign > bsign) {
            result = 1;
        }
    }

    return result;
}

