    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.bytes.add((byte) 0x00);
        }
        return this;
    }
    // Check for invalid offset and length
    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid offset or length");
    }
    // Copy the bytes
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        this.bytes.add(byteArrayValue[i]);
    }
    return this;
}

public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    // Check for null or invalid input
    if (byteArrayValue == null) {
        throw new IllegalArgumentException("Byte array input cannot be null");
    }
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IllegalArgumentException("Byte offset is out of bounds");
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("Byte length is out of bounds");
    }

    // Ensure the array has enough space and copy the bytes over
    if (byteLength + this.size() > this.byteArray.length) {
        byte[] newByteArray = new byte[Math.max(this.size() + byteLength, this.byteArray.length * 2)];
        System.arraycopy(this.byteArray, 0, newByteArray, 0, this.size());
        this.byteArray = newByteArray;
    }
    System.arraycopy(byteArrayValue, byteOffset, this.byteArray, this.size(), byteLength);

    // Update the size
    this.size += byteLength;

    // Return this for chaining
    return this;
}

