    }

    // Calculate the available space in the byte vector
    int availableSpace = buf.length - pos;

    // Check if the byte array is too large for the byte vector
    if (byteLength > availableSpace) {
        // Enlarge the byte vector if necessary
        ensureCapacity(pos + byteLength);
    }

