            continue;
        }

        // If the uriChar is not equal to the patternChar and the patternChar is a wildcard, continue to the next iteration
        if (patternChar == '*') {
            nextIndex = i + 1;
            break;
        }

        // If the uriChar is not equal to the patternChar and the patternChar is not a wildcard, return null
        return null;
    }

    // Return the match result if the uri fully matches the pattern
    if (nextIndex == uri.length()) {
        return matchResult;
    }

    // Return null if the uri does not fully match the pattern
    return null;
}

private static String[] extractParts(String template) {
    List<String> parts = new ArrayList<>();
    StringBuilder partBuilder = new StringBuilder();
    boolean inVariable = false;
    for (int i = 0; i < template.length(); i++) {
        char c = template.charAt(i);
        if (!inVariable) {
            if (c == '{') {
                inVariable = true;
            } else {
                partBuilder.append(c);
            }
        } else {
            if (c == '}') {
                inVariable = false;
                parts.add(partBuilder.toString());
                partBuilder.setLength(0);
            } else {
                partBuilder.append(c);
            }
        }
    }
    if (inVariable) {
        parts.add(partBuilder.toString());
    }
    return parts.toArray(new String[0]);
}

// A class to represent the match result
public static class MatchResult {
    private final int numMatches;
    private final Map<String, String> matches;

    public MatchResult(int numMatches) {
        this.numMatches = numMatches;
        this.matches = new HashMap<>();
    }

    public void addMatch(String key, String value) {
        matches.put(key, value);
    }

    public int getNumMatches() {
        return numMatches;
    }

    public Map<String, String> getMatches() {
        return matches;
    }
}

public final MatchResult match(CharSequence uri) {
    // Initialize the match result as a null value
    MatchResult result = null;

    // Check if the input URI is null or empty
    if (uri == null || uri.length() == 0) {
        // If the input URI is null or empty, return null
        return result;
    }

    // Split the URI into its components
    String[] parts = uri.split("/");

    // Initialize the variable to keep track of the current component
    int currentComponent = 0;

    // Iterate over the components of the URI
    for (String part : parts) {
        // Check if the current component is a wildcard
        if (part.equals("*")) {
            // If the current component is a wildcard, return a match result with the wildcard component
            result = new MatchResult(part, currentComponent);
            break;
        }

        // Check if the current component is a variable
        if (part.startsWith("{") && part.endsWith("}")) {
            // If the current component is a variable, return a match result with the variable component
            result = new MatchResult(part, currentComponent);
            break;
        }

        // Increment the current component
        currentComponent++;
    }

    // Return the match result
    return result;
}

public final MatchResult match(CharSequence uri) {
    // Edge case: Empty URI
    if (uri.length() == 0) {
        return null;
    }

    // Edge case: Matches the entire template
    if (uri.equals(template)) {
        return new MatchResult(template);
    }

    Pattern pattern = Pattern.compile(template);
    Matcher matcher = pattern.matcher(uri);

    // Check if the URI matches the template
    if (matcher.matches()) {
        return new MatchResult(matcher.group(1));
    }

    return null;
}

public static byte convertHexDigit(byte b) {
