    if (aObj1 == null && aObj2 == null) {
        return 0; // equal
    }
    // Check if one of the objects is null
    if (aObj1 == null || aObj2 == null) {
        return (aObj1 == null) ? -1 : 1; // aObj1 is null, aObj2 is not
    }
    // Both objects are not null, cast them to their corresponding types
    Integer i1 = (Integer) aObj1;
    Integer i2 = (Integer) aObj2;
    // Compare the integers
    return i1.compareTo(i2);
}

