static void register(Object value) {
    // Check if value is null
    if (value == null) {
        throw new NullPointerException("Value must not be null");
    }

    // Check if the value is already registered
    if (registeredObjects.contains(value)) {
        throw new IllegalArgumentException("Object already registered");
    }

    // Add the value to the list of registered objects
    registeredObjects.add(value);
}

public static void register(Object value) {
	// If the given value is a primitive, return immediately
	if (value instanceof String || value instanceof Character || value instanceof Number || value instanceof Boolean) {
		return;
	}

	// If the value is an array, register each element
	if (value.getClass().isArray()) {
		for (int i = 0; i < Array.getLength(value); i++) {
			register(Array.get(value, i));
		}
		return;
	}

	// If the value is an Iterable, register each element
	if (value instanceof Iterable) {
		for (Object element : (Iterable)value) {
			register(element);
		}
		return;
	}

	// If the value is a collection, register each element
	if (value instanceof Collection) {
		for (Object element : (Collection)value) {
			register(element);
		}
		return;
	}

	// If the value is a map, register each key and value
	if (value instanceof Map) {
		for (Map.Entry entry : ((Map)value).entrySet()) {
			register(entry.getKey());
			register(entry.getValue());
		}
		return;
	}

	// If the value is an object or a proxy, register its fields and methods
	registerObject(value);
}

