protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Check if the input is valid
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Null input");
    }

    // Get the number of vertices in the graph
    int numVertices = graph.vertexSet().size();

    // Create a new graph path with the same number of vertices as the graph
    GraphPath<V, E> path = new GraphPathImpl<>(numVertices);

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Get the vertices of the edge
        V v1 = graph.getEdgeSource(edge);
        V v2 = graph.getEdgeTarget(edge);

        // Add the edge to the path
        path.addEdge(v1, v2, edge);
    }

    return path;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Check if the input set is empty
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set is empty");
    }

    // Create a list to store the vertices in the tour
    List<V> vertices = new ArrayList<>();

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the vertices of the current edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the vertices to the list if they are not already in it
        if (!vertices.contains(source)) {
            vertices.add(source);
        }
        if (!vertices.contains(target)) {
            vertices.add(target);
        }
    }

    // Create a graph path from the list of vertices
    return new GraphPath<>(graph, vertices);
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Invalid input: tour and graph must not be null");
    }

    // Create a new graph path with capacity equal to the size of the tour
    GraphPath<V, E> path = new GraphPath<>(graph, tour.size());

    // Add the edges of the tour to the path
    for (E edge : tour) {
        path.add(edge);
    }

    // Return the completed path
    return path;
}

@Override
protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Validate the input parameters
    if (tour == null || graph == null || tour.size() == 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Initialize the output graph path
    GraphPath<V, E> result = new GraphPathImpl<>(null, null);

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Check if the edge is contained in the graph
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour contains edge not present in graph");
        }

        // Add the edge to the output graph path
        result.addEdge(edge);
    }

    // Return the output graph path
    return result;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize a new graph path with the edges of the tour
    GraphPath<V, E> path = new GraphPath<V, E>(graph.getNodes(), graph.getEdgeFactory());

    // Add each edge in the tour to the path
    for (E edge : tour) {
        path.addEdge(edge);
    }

    // Return the path
    return path;
}

