}

public String unescapeId(String input) {
    // Step 1: Check for null or empty input
    if (input == null || input.isEmpty()) {
        return input;
    }

    // Step 2: Replace backslash-escaped characters
    String output = input.replaceAll("\\\\(\\\\.|['\"]|/|\\|)","$1");

    // Step 3: Unescape single quotes
    output = output.replaceAll("''","'");

    // Step 4: Unescape double quotes
    output = output.replaceAll("\"\"","\"");

    // Step 5: Return the unescaped output
    return output;
}

public String unescapeId(String input) {
    // Handle null input
    if (input == null) {
        return null;
    }

    // Handle empty input
    if (input.trim().isEmpty()) {
        return "";
    }

    // Get the first character
    char firstChar = input.charAt(0);

    // Check if the first character is a backslash
    if (firstChar == '\\') {
        // Get the second character
        char secondChar = input.charAt(1);

        // Check if the second character is a single quote
        if (secondChar == '\'') {
            // Return the input without the first backslash and single quote
            return input.substring(1, input.length() - 1);
        }
    }

    // Return the input as is
    return input;
}

