private Class findClass(final String className) throws ClassNotFoundException {

    // Validate input
    if (className == null) {
        throw new IllegalArgumentException("Class name cannot be null");
    }

    // Try to load class using class loader
    try {
        return Class.forName(className);
    } catch (ClassNotFoundException e) {
        // Class not found, try to load as inner class
        int lastDotIndex = className.lastIndexOf('.');
        if (lastDotIndex != -1) {
            // Inner class, try loading outer class first
            String outerClassName = className.substring(0, lastDotIndex);
            Class<?> outerClass = findClass(outerClassName);
            if (outerClass != null) {
                // Outer class found, try loading inner class
                String innerClassName = className.substring(lastDotIndex + 1);
                return outerClass.getDeclaredClasses().stream()
                        .filter(innerClass -> innerClass.getSimpleName().equals(innerClassName))
                        .findFirst()
                        .orElseThrow(() -> new ClassNotFoundException("Inner class " + className + " not found"));
            }
        }
        // Class not found
        throw e;
    }
}

