protected V provideNextVertex() {
    // Step 1: Check if there are any available vertices in the queue
    if (queue.isEmpty()) {
        // Step 2: If there are no available vertices, return null
        return null;
    }

    // Step 3: Get the next vertex from the queue
    V vertex = queue.poll();

    // Step 4: If the vertex is not marked as visited, mark it as visited and return it
    if (!vertex.isVisited()) {
        vertex.setVisited(true);
        return vertex;
    }

    // Step 5: If the vertex is marked as visited, get its neighbors
    Set<V> neighbors = vertex.getNeighbors();

    // Step 6: For each neighbor, check if it is marked as visited
    for (V neighbor : neighbors) {
        // Step 7: If the neighbor is not marked as visited, add it to the queue
        if (!neighbor.isVisited()) {
            queue.add(neighbor);
        }
    }

    // Step 8: Return the next vertex from the queue
    return provideNextVertex();
}

