            // - Maintaining a separate data structure to track the vertex with the highest weight
            // - Maintaining a separate data structure to track the vertex with the highest weight (e.g., via a map)
            for (int i = 1; i < nextVertex.getOutgoingEdges().size(); i++) {
                if (nextVertex.getOutgoingEdge(i).getWeight() > nextVertex.getOutgoingEdge(0).getWeight()) {
                    nextVertex = nextVertex.getOutgoingEdge(i);
