public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> previous = node.previous;
    ListNodeImpl<E> next = node.next;

    if (previous == null) {
        // node is the first node in the list, unlink it from the list
        next.previous = null;
        head = next;
    } else if (next == null) {
        // node is the last node in the list, unlink it from the list
        previous.next = null;
        tail = previous;
    } else {
        // node is an inner node in the list, unlink it from the list
        previous.next = next;
        next.previous = previous;
    }

    node.previous = null;
    node.next = null;

    size--;

    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // Find the node's previous and next pointers
    ListNodeImpl<E> prevNode = node.getPrev();
    ListNodeImpl<E> nextNode = node.getNext();

    // Connect the previous and next nodes
    if (prevNode != null) {
        prevNode.setNext(nextNode);
    }
    if (nextNode != null) {
        nextNode.setPrev(prevNode);
    }

    // Clear the node's previous and next pointers
    node.setPrev(null);
    node.setNext(null);

    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    // Check if the node is null
    if (node == null) {
        return false;
    }

    // Check if the node is the head of the list
    if (node == head) {
        head = head.getNext();
        return true;
    }

    // Find the previous node in the list
    ListNodeImpl<E> prev = head;
    while (prev.getNext() != node) {
        prev = prev.getNext();
    }

    // Unlink the node from the list
    prev.setNext(node.getNext());
    node.setNext(null);

    return true;
}

