    if (node == null) {
        return false;
    }

    boolean isNodeRemoved = false;

    if (node.previous != null) {
        node.previous.next = node.next;
        isNodeRemoved = true;
    }

    if (node.next != null) {
        node.next.previous = node.previous;
    }

    if (node.next == null && node.previous == null) {
        isNodeRemoved = false;
    }

    return isNodeRemoved;
}

