    if (node == null || node.next == null) {
        return false;
    }

    ListNodeImpl<E> current = node.next;
    ListNodeImpl<E> previous = node;

    while (current != null) {
        ListNodeImpl<E> next = current.next;
        current.next = previous;
        previous = current;
        current = next;
