public static String trimLeadingCharacter(String str, char leadingCharacter) {
    // Check for null inputs
    if (str == null || leadingCharacter == '\0') {
        throw new IllegalArgumentException("Input string or leading character cannot be null");
    }

    // Create a new string builder with the same length as the original string
    StringBuilder builder = new StringBuilder(str.length());

    // Iterate over the characters in the string
    for (int i = 0; i < str.length(); i++) {
        // If the current character is not the leading character, append it to the builder
        if (str.charAt(i) != leadingCharacter) {
            builder.append(str.charAt(i));
        }
    }

    // Return the trimmed string
    return builder.toString();
}

