private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        // Edge case: Empty list
        if (bounds.isEmpty()) {
            return new Pair<>(Collections.emptyList(), 0L);
        }

        // Initialize variables for the accumulated sum and the result list
        long sum = 0;
        List<Integer> result = new ArrayList<>();

        // Iterate from the end of the list to the beginning
        for (int i = bounds.size() - 1; i >= 0; i--) {
            sum += bounds.get(i);
            result.add((int) sum);
        }

        // Return the computed pair of the result list and the sum of all elements
        return new Pair<>(result, sum);
    }

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        int sum = 0;
        for (int j = i; j < bounds.size(); j++) {
            sum += bounds.get(j);
        }
        suffixSumList.add(sum);
        totalSum += sum;
    }

    return new Pair<>(suffixSumList, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Check if the input list is empty
    if (bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    // Initialize the result list and sum
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0L;

    // Iterate over the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the suffix sum and total sum
        int currentSum = totalSum + bounds.get(i);
        suffixSum.add(currentSum);
        totalSum = currentSum;
    }

    // Return the computed suffix sum and total sum
    return new Pair<>(suffixSum, totalSum);
}

public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Step 1: Handle potential null or empty bounds list
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty.");
    }

    // Step 2: Initialize variables
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(bounds.size(), 0));
    suffixSum.set(0, bounds.get(0));
    long sum = bounds.get(0);

    // Step 3: Loop through the bounds list and compute suffix sum
    for (int i = 1; i < bounds.size(); i++) {
        suffixSum.set(i, suffixSum.get(i - 1) + bounds.get(i));
        sum += bounds.get(i);
    }

    // Step 4: Return pair of suffix sum list and sum of all elements
    return new Pair<>(suffixSum, sum);
}

