        // Validate inputs
        if (bounds == null || bounds.isEmpty()) {
            throw new IllegalArgumentException("Bounds must not be null or empty");
        }

        // Compute suffix sum

        long sum = 0L;
        List<Integer> suffixSum = new ArrayList<>(bounds.size());
        for (int i = 0; i < bounds.size(); i++) {
            sum += bounds.get(i);
            suffixSum.add(sum);
        }

        return new Pair<>(suffixSum, sum);
    }

public static final void reverse(V[] arr, int from, int to) {
    // Check if the input is valid
    if (from < 0 || to < from || to >= arr.length) {
        throw new IllegalArgumentException("Invalid range specified");
    }

    // Reverse the elements in the range
    for (int i = from, j = to; i < j; i++, j--) {
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (from > to) {
        throw new IllegalArgumentException("'from' index must be less than or equal to 'to' index");
    }
    if (from < 0 || to > arr.length - 1) {
        throw new IndexOutOfBoundsException("'from' and 'to' indices must be valid indices of the array");
    }

    int i = from, j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

