    // Handle edge cases
    if (from < 0 || to >= arr.length || from > to) {
        throw new IndexOutOfBoundsException("Invalid range");
    }

    // Reverse the range
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to < 0 || from > to) {
        // handle invalid inputs with exception-handling behavior as appropriate
        throw new IllegalArgumentException("Invalid input");
    }

    // swap elements from and to
    V temp = arr[from];
    arr[from] = arr[to];
    arr[to] = temp;

    // recursively reverse the remaining elements
    if (from + 1 < to) {
        reverse(arr, from + 1, to - 1);
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Check if the input is valid
    if (arr == null || from < 0 || to > arr.length || from > to) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Reverse the elements in the specified range
    for (int i = from; i <= to; i++) {
        V temp = arr[i];
        arr[i] = arr[from];
        arr[from] = temp;
        from++;
    }
}

