    // Step 2: Check if the event.getMessage() contains the configured string
    String msg = event.getMessage();
    if (msg == null || !msg.contains(getSearchString())) {
        return Filter.NEUTRAL;
    }

    // Step 3: Check the event.getLevel() and return the appropriate decision
    Level level = event.getLevel();
    if (level == Level.ERROR || level == Level.FATAL) {
        return Filter.ACCEPT;
    } else if (level == Level.WARN) {
        return Filter.NEUTRAL;
    } else {
        return Filter.DENY;
    }
}

