public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Validate input
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }

    // Select the specified row
    table.setRowSelectionInterval(row, row);

    // Get the table's visible rectangle
    Rectangle visibleRect = table.getVisibleRect();

    // Get the y-coordinate of the specified row
    int rowY = table.getCellRect(row, 0, true).y;

    // Calculate the new vertical position for the scroll pane
    int newVerticalPosition = rowY - visibleRect.height / 2 + row.getHeight() / 2;

    // Scroll the pane to the new position
    pane.getViewport().setViewPosition(new Point(0, newVerticalPosition));

