public ByteVector putInt(int intValue) {
    // Step 1: Check if the input value is a valid integer
    if (intValue < 0 || intValue > 256) {
        throw new IllegalArgumentException("Input value out of range: " + intValue);
    }

    // Step 2: Get the number of bytes needed to represent the input value
    int bytesNeeded = (int) Math.ceil(Math.log(intValue) / Math.log(256));

    // Step 3: Enlarge the byte vector if necessary
    if (bytesNeeded > this.bytes.length) {
        this.bytes = Arrays.copyOf(this.bytes, bytesNeeded);
    }

    // Step 4: Convert the input value to bytes and store them in the byte vector
    for (int i = 0; i < bytesNeeded; i++) {
        this.bytes[i] = (byte) (intValue & 0xFF);
        intValue = intValue >> 8;
    }

    return this;
}

