private static boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // check if the given vertices are a subset of the graph vertices
    if (!graph.getVertices().containsAll(vertices)) {
        throw new IllegalArgumentException("The given vertices are not a subset of the graph vertices");
    }

    // check if the given vertices form a clique
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.hasEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // check if vertices is null or empty
    if (vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("vertices cannot be null or empty");
    }

    // check if graph is null
    if (graph == null) {
        throw new IllegalArgumentException("graph cannot be null");
    }

    // create a new Set to store the adjacent vertices of each vertex
    Set<V> adjVertices = new HashSet<>();

    // iterate over each vertex in the graph
    for (V vertex : graph.vertexSet()) {
        // if the vertex is in the induced subgraph
        if (vertices.contains(vertex)) {
            // add the adjacent vertices to the adjacent vertices set
            adjVertices.addAll(graph.adjacentVertices(vertex));
        }
    }

    // check if the adjacent vertices set contains all the vertices in the induced subgraph
    return adjVertices.containsAll(vertices);
}

