private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a valid subgraph
    if (vertices.size() < 2) {
        throw new IllegalArgumentException("The number of vertices must be at least 2");
    }

    // Initialize the set of connected vertices
    Set<V> connectedVertices = new HashSet<>();

    // Iterate over the vertices and mark connected vertices
    for (V vertex : vertices) {
        connectedVertices.add(vertex);
        for (E edge : graph.getEdges(vertex)) {
            V adjacentVertex = graph.getEdgeTarget(vertex, edge);
            if (connectedVertices.contains(adjacentVertex)) {
                // Break if there are any disconnected vertices
                break;
            } else {
                connectedVertices.add(adjacentVertex);
            }
        }
    }

    // Check if all vertices are connected
    return connectedVertices.equals(vertices);
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the input graph and vertices are valid
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Input graph and vertices cannot be null");
    }

    // Get all the vertices in the graph
    Set<V> allVertices = new HashSet<>(graph.vertices());

    // Check if the given vertices is a subset of the graph vertices
    if (!allVertices.containsAll(vertices)) {
        throw new IllegalArgumentException("Given vertices is not a subset of the graph vertices");
    }

    // Get the subgraph induced by the given vertices
    Graph<V, E> inducedSubgraph = graph.getInducedSubgraph(vertices);

    // Check if the subgraph is complete
    if (inducedSubgraph.numEdges() == vertices.size() * (vertices.size() - 1) / 2) {
        return true;
    }

    return false;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    // Iterate through the keys and compute the lower bounds
    for (K key : keys) {
        int lowerBound = -1;
        // Check if the key is present in the list
        if (key != null) {
            int index = keys.indexOf(key);
            if (index >= 0) {
                lowerBound = index + 1;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
	// Initialize the lower bounds list with 0 for each key
	List<Integer> lowerBounds = new ArrayList<>(keys.size());
	for (int i = 0; i < keys.size(); i++) {
		lowerBounds.add(0);
	}

	// Iterate over the keys and compute the minimum value greater than or equal to the current key
	for (int i = 0; i < keys.size(); i++) {
		for (int j = i + 1; j < keys.size(); j++) {
			if (keys.get(j).compareTo(keys.get(i)) > 0) {
				lowerBounds.set(i, Math.max(lowerBounds.get(i), keys.get(j).compareTo(keys.get(i))));
			}
		}
	}

	// Return the computed lower bounds list
	return lowerBounds;
}

