    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        lowerBounds.add(Integer.MIN_VALUE);
    }

    // Step 2: Loop through the keys and update the lower bounds
    for (int i = 0; i < keys.size(); i++) {
        for (int j = 0; j < keys.size(); j++) {
            if (i != j && keys.get(i).compareTo(keys.get(j)) <= 0) {
                lowerBounds.set(i, Math.max(lowerBounds.get(i), keys.get(j)));
            }
        }
    }

    // Step 3: Return the final lower bounds
    return lowerBounds;
}

