            }
        }
        lowerBounds.add(bound);
    }
    return lowerBounds;
}

public void pop(final String descriptor) {
    // Check if the provided descriptor is a method descriptor
    if (descriptor.contains("(")) {
        // Get the method descriptor
        final String methodDescriptor = descriptor.substring(descriptor.indexOf("(") + 1);
        // Get the argument types of the method
        final String[] argTypes = methodDescriptor.substring(0, methodDescriptor.indexOf(")")).split(";");
        // Pop the argument types from the output frame stack
        for (String argType : argTypes) {
            pop(argType);
        }
    } else {
        // The provided descriptor is a type descriptor
        final String typeArg;
        try {
            typeArg = Type.getType(descriptor).getDescriptor();
        } catch (Exception e) {
            throw new RuntimeException("Failed to obtain the type argument of the descriptor " + descriptor, e);
        }
        // Pop the type argument from the output frame stack
        pop(typeArg);
    }
}

public void pop(String descriptor) {
    if (descriptor.startsWith("(")) {
        // Pop argument types
        List<AbstractType> types = new ArrayList<>();
        while (descriptor.charAt(0) == '(') {
            descriptor = descriptor.substring(1);
            types.add(pop());
        }
        push(new MethodType(types));
    } else {
        // Pop a single abstract type
        push(pop());
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }

    // Parse the descriptor to determine the number of types to pop
    int numTypesToPop = 1;
    if (descriptor.startsWith("(")) {
        numTypesToPop = Type.getArgumentTypes(descriptor).length;
    }

    // Pop the required number of types from the output frame stack
    for (int i = 0; i < numTypesToPop; i++) {
        final Object poppedType = outputFrameStack.pop();
        if (poppedType == null) {
            throw new RuntimeException("Encountered unnecessary type " + descriptor + " on the output frame stack");
        }
    }
}

private void pop(String descriptor) {
    int numTypes = descriptor.charAt(0) - 'A';
    for (int i = 0; i < numTypes; i++) {
        outputFrameStack.pop();
    }
}

