public static String applyRelativePath(String path, String relativePath) {
    // validate input parameters
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    // ensure path separators are consistent
    if (!path.contains("/") || !relativePath.contains("/")) {
        throw new IllegalArgumentException("Path separators must be \"/\"");
    }
    // extract parent path and filename components
    String parentPath = path.substring(0, path.lastIndexOf('/') + 1);
    String filename = path.substring(path.lastIndexOf('/') + 1);
    // combine parent path and relative path components
    String combinedPath = parentPath + relativePath;
    // remove any duplicate "/" characters
    combinedPath = combinedPath.replaceAll("/+", "/");
    // check for invalid characters in the combined path
    if (combinedPath.contains("..") || combinedPath.contains("//")) {
        throw new IllegalArgumentException("Invalid relative path");
    }
    // construct the full file path
    return combinedPath + filename;
}

public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relative path into individual parts
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Iterate through the relative path parts and apply them to the path
    for (int i = 0; i < relativePathParts.length; i++) {
        // If the current part of the relative path is "..", remove the last part of the path
        if (relativePathParts[i].equals("..")) {
            pathParts = Arrays.copyOfRange(pathParts, 0, pathParts.length - 1);
        }
        // If the current part of the relative path is not "..", add it to the end of the path
        else {
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = relativePathParts[i];
        }
    }

    // Join the path parts back into a single string
    return String.join("/", pathParts);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new NullPointerException("Path and relative path cannot be null");
    }
    // split the path into its components
    String[] pathComponents = path.split("/");
    // split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");
    // create a new list to store the resulting components
    List<String> resultingComponents = new ArrayList<>();
    // iterate over the components of the path
    for (int i = 0; i < pathComponents.length; i++) {
        // if the component is "..", remove the last component from the resulting list
        if (pathComponents[i].equals("..")) {
            resultingComponents.remove(resultingComponents.size() - 1);
        // otherwise, add the component to the resulting list
        } else {
            resultingComponents.add(pathComponents[i]);
        }
    }
    // iterate over the components of the relative path
    for (int i = 0; i < relativePathComponents.length; i++) {
        // if the component is "..", remove the last component from the resulting list
        if (relativePathComponents[i].equals("..")) {
            resultingComponents.remove(resultingComponents.size() - 1);
        // otherwise, add the component to the resulting list
        } else {
            resultingComponents.add(relativePathComponents[i]);
        }
    }
    // join the resulting components into a single string
    String resultingPath = String.join("/", resultingComponents);
