    return resultingPath;
}

public static String applyRelativePath(String path, String relativePath) {
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is absolute
    if (relativePathComponents[0].equals(".")) {
        // If the first component is ".", it means the path is absolute and we can simply return it
        return relativePath;
    }

    // Check if the relative path is relative to the current directory
    if (relativePathComponents[0].equals("..")) {
        // If the first component is "..", it means the path is relative to the current directory
        // We'll need to remove the last component of the path to get the parent directory
        String parentPath = path.substring(0, path.lastIndexOf("/"));
        return parentPath + "/" + relativePath;
    }

    // If the relative path is not absolute or relative to the current directory,
    // we'll need to append it to the end of the path
    return path + "/" + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty inputs
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    // Split the path and relative path into lists of substrings based on the separator "/"
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Initialize a list to store the new path parts
    List<String> newPathParts = new ArrayList<>();

    // Iterate through the relative path parts and determine whether they should be added to the new path
    for (String relativePathPart : relativePathParts) {
        if (relativePathPart.equals("..")) {
            // If the relative path part is "..", remove the last path part from the new path
            if (newPathParts.size() > 0) {
                newPathParts.remove(newPathParts.size() - 1);
            }
        } else if (relativePathPart.equals(".")) {
            // If the relative path part is ".", do nothing
        } else {
            // If the relative path part is not ".." or ".", add it to the new path
            newPathParts.add(relativePathPart);
        }
    }

    // Join the new path parts into a single string, separating them with "/"
    String newPath = String.join("/", newPathParts);

    // If the new path is empty, return the current directory "/"
    if (newPath.isEmpty()) {
        return "/";
    }

    // Return the new path
    return newPath;
}

