    if (lastSeparatorIndex > lastDotIndex) {
        return lastSeparatorIndex;
    }
    return lastDotIndex;
}

// Return the index of the last extension separator character, which is a dot.
// This method also checks that there is no directory separator after the last dot.
int lastSeparator = indexOfLastSeparator(filename);
if (lastSeparator == -1) {
    return -1;
}
int firstDot = filename.indexOf('.', lastSeparator + 1);
if (firstDot > lastSeparator + 1) {
