public static int indexOfExtension(String filename) {
    // Check for null or empty file name
    if (filename == null || filename.isEmpty()) {
        return -1;
    }

    // Find the last index of a dot character
    int dotIndex = filename.lastIndexOf(".");

    // If the dot is not found, return -1
    if (dotIndex == -1) {
        return -1;
    }

    // Check if there is a directory separator after the last dot
    if (filename.indexOfAny(new char[] {'/', '\\'}, dotIndex + 1) != -1) {
        return -1;
    }

    // Return the index of the last dot
    return dotIndex;
}

// Pattern for matching extension separators
static final Pattern EXTENSION_SEPARATOR = Pattern.compile("\\.");

// Find the last extension separator character
int extensionSeparatorIndex = EXTENSION_SEPARATOR.lastIndexOf(filename);

// If there is no extension separator, return immediately
if (extensionSeparatorIndex == -1) {
    return -1;
}

// Find the last directory separator character
int lastSeparatorIndex = indexOfLastSeparator(filename);

// If there is no directory separator after the extension separator, return the index of the extension separator
if (lastSeparatorIndex < extensionSeparatorIndex) {
    return extensionSeparatorIndex;
}

// If there is a directory separator after the extension separator, return -1
return -1;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    return lastSeparator > -1 && lastSeparator < filename.length() - 2 && filename.charAt(lastSeparator + 1) == '.'
            ? lastSeparator
            : -1;
}

