public void handleLogEvent(LoggingEvent event) {
    // Handle the log event by writing the message to each connected client
    for (Client client : clients) {
        try {
            client.write(event.getMessage());
        } catch (IOException e) {
            // Handle potential IO exceptions by logging the error and disconnecting the client
            LOG.error("An error occurred while writing to client: " + client, e);
            disconnectClient(client);
        }
    }
}

public void disconnectClient(Client client) {
    // Disconnect the client from the server
    clients.remove(client);
    client.close();
}

