private void append(LoggingEvent event) {
    // Check if the event is null
    if (event == null) {
        throw new NullPointerException("Event cannot be null");
    }

    // Get the message from the event
    String message = event.getMessage();

    // Get the clients from the appender
    List<Client> clients = getClients();

    // Loop through the clients and write the message to each one
    for (Client client : clients) {
        try {
            client.write(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

public void append(LoggingEvent event) {
    // Verify that the event is not null
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    try {
        // Get the message and the source of the log event
        String message = event.getMessage();
        String source = event.getSource();

        // Iterate over all connected clients and send the log message
        for (Client client : clients) {
            client.write(message + " [" + source + "]");
        }
    } catch (IOException e) {
        // Exception handling for IOException
        logger.error("Error writing to client", e);
    }
}

protected void append(LoggingEvent event) {
    try {
        // Get the connected clients
        Set<Socket> clients = getConnectedClients();

        // Loop through each client and write the log message to it
        for (Socket client : clients) {
            try (OutputStream out = client.getOutputStream()) {
                // Write the log message to the client
                out.write(event.getMessage().getBytes());
            }
        }
    } catch (IOException e) {
        // Log the exception and continue with other clients
        logger.log(Level.WARNING, "Failed to write log message to client", e);
    }
}

