    if (fieldNumber <= 0) {
        throw new IllegalArgumentException("Invalid field number: " + fieldNumber);
    }
    if (isCurrentFieldPacked) {
        // Get the length of the packed field and skip over it
        int length = input.readRawVarint32();
        input.skipRawBytes(length);
    }
}

