public ByteVector put11(int byteValue1, int byteValue2) {
    // Check for null pointer
    if (this.data == null) {
        this.data = new byte[16];
    }

    // Check for sufficient capacity
    int requiredCapacity = Math.max(this.data.length, this.dataLength + 2);
    if (this.data.length < requiredCapacity) {
        byte[] newData = new byte[requiredCapacity];
        System.arraycopy(this.data, 0, newData, 0, this.dataLength);
        this.data = newData;
    }

    // Put the bytes
    this.data[this.dataLength++] = (byte) byteValue1;
    this.data[this.dataLength++] = (byte) byteValue2;

    return this;
}

public ByteVector put11(final int byteValue1, final int byteValue2) {
    // Automatically enlarge the byte vector if necessary
    if (this.size() < this.limit()) {
        this.resize(this.size() + 2);
    }
    // Put the two bytes into the vector
    this.set(0, byteValue1);
    this.set(1, byteValue2);
    return this;
}

public ByteVector put11(int byteValue1, int byteValue2) {
    //resize the byte vector if necessary
    if (size() < 2) {
        ensureCapacity(2);
    }

    //put the two bytes into the byte vector
    byte[] bytes = toByteArray();
    bytes[0] = (byte) byteValue1;
    bytes[1] = (byte) byteValue2;

    //update the size of the byte vector
    size = 2;

    //return the byte vector
    return this;
}

private ByteVector put11(byte byteValue1, byteValue2) throws IOException {
    // Step 1: Check if the byte vector needs to be enlarged
    if (this.capacity() < this.size() + 2) {
        // Enlarge the byte vector by 2 bytes
        this.enlarge();
    }

    // Step 2: Write the byte values into the byte vector
    this.put(byteValue1);
    this.put(byteValue2);

    // Step 3: Return the byte vector
    return this;
}

public final ByteVector put11(int byteValue1, int byteValue2) {
	// Check if the byte vector needs to be enlarged
	if (this.length() < this.limit()) {
		// Calculate the number of bytes needed to be enlarged
		int enlargeBytes = this.limit() - this.length();

		// Enlarge the byte vector by the calculated number of bytes
		this.enlarge(enlargeBytes);
	}

	// Write the byte values into the byte vector
	this.put1(byteValue1);
	this.put1(byteValue2);

	// Return the byte vector
	return this;
}

private String buildContentRange() {
    // Validate parameters
    if (start == null || end == null || total == null) {
        throw new IllegalArgumentException("All parameters must be specified");
    }

    // Calculate the 'Content-Range' value
    return String.format("bytes %d-%d/%d", start, end, total);
}

public String buildContentRange() {
    int firstBytePosition = 0;
    int lastBytePosition = -1;
    long totalNumberOfBytes = 0L;

    // Calculate the first and last byte positions, and the total number of bytes in the content.
    firstBytePosition = getFirstBytePosition();
    lastBytePosition = getLastBytePosition();
    totalNumberOfBytes = getContentLength();

    // Build the 'Content-Range' value.
    return String.format("bytes %d-%d/%d", firstBytePosition, lastBytePosition, totalNumberOfBytes);
}

private String buildContentRange() {
    // Check if the resource can be divided into multiple parts
    if (isDivisible(resourceLength)) {
        // Calculate the size of each part
        int partLength = (int) (resourceLength / numberOfParts);
        // Build the Content-Range header
        return "Content-Range: bytes " + partLength + " " + resourceLength + "/" + resourceLength;
    } else {
        return "";
    }
}

private String buildContentRange() {
    // Calculate the range of the Content-Range header
    int start = 0;
    int end = content.length() - 1;
    String range = "bytes " + start + "-" + end + "/" + content.length();

    // Return the Content-Range header value
    return range;
}

public String buildContentRange() {
    // Calculate the file size
    long fileSize = calculateFileSize();
    // Calculate the content range
    String contentRange = calculateContentRange(fileSize);
    // Return the content range
    return contentRange;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Open the file to read
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line
            String[] tokens = line.split(":");

            // Check if the line is a valid snapshot
            if (tokens.length != 3) {
                continue;
            }

            // Get the timestamp and the snapshot data
            long timestamp = Long.parseLong(tokens[0]);
            String snapshotData = tokens[2];

            // Check if the snapshot data is valid
            if (snapshotData.isEmpty()) {
                continue;
            }

            // Extract the thread ID and the stack trace
            String[] threadIdAndStackTrace = snapshotData.split("\t");

            // Check if the thread ID and stack trace are valid
            if (threadIdAndStackTrace.length != 2) {
                continue;
            }

            // Extract the thread ID and the stack trace
            long threadId = Long.parseLong(threadIdAndStackTrace[0]);
            String stackTrace = threadIdAndStackTrace[1];

            // Check if the thread ID and stack trace are valid
            if (threadId <= 0 || stackTrace.isEmpty()) {
                continue;
            }

            // Create a new thread snapshot
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadId, stackTrace);

            // Check if the time range of the snapshot is within the specified time range
            boolean isWithinRange = timeRanges.stream()
                    .anyMatch(timeRange -> timeRange.contains(timestamp));

            // Add the snapshot to the list if it is within the specified time range
            if (isWithinRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    // Return the list of thread snapshots
    return threadSnapshots;
}

public static List<ThreadSnapshot> loadSnapshots(File file, List<ProfileAnalyzeTimeRange> timeRanges) {
    try {
        ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file));
        List<ThreadSnapshot> snapshots = new ArrayList<>();
        while (ois.available() > 0) {
            ThreadSnapshot snapshot = (ThreadSnapshot) ois.readObject();
            if (isInTimeRange(snapshot.getCreationTime(), timeRanges)) {
                snapshots.add(snapshot);
            }
        }
        ois.close();
        return snapshots;
    } catch (IOException | ClassNotFoundException e) {
        e.printStackTrace();
    }
    return null;
}

private static boolean isInTimeRange(Date creationTime, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (range.isInRange(creationTime)) {
            return true;
        }
    }
    return false;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(
        File file,
        List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        int lineNumber = 0;

        while ((line = reader.readLine()) != null) {
            lineNumber++;
            // Parse the line and check if it is a snapshot line
            if (!line.startsWith("S")) {
                continue;
            }
            // Get the time of the snapshot
            String timeString = line.substring(1, 15);
            String[] timeTokens = timeString.split(":");
            int hour = Integer.parseInt(timeTokens[0].trim());
            int minute = Integer.parseInt(timeTokens[1].trim());
            int second = Integer.parseInt(timeTokens[2].trim());
            int milisecond = Integer.parseInt(timeTokens[3].trim());
            // Create a new snapshot object
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            threadSnapshot.setTime(hour, minute, second, milisecond);
            // Read the next line and check if it is a metrics line
            line = reader.readLine();
            lineNumber++;
            if (line == null) {
                continue;
            }
            if (!line.startsWith("M")) {
                continue;
            }
            // Parse the metrics line and set the metrics values
            String[] metricTokens = line.split(",");
            threadSnapshot.setMetrics(
                Integer.parseInt(metricTokens[1].trim()),
                Integer.parseInt(metricTokens[2].trim()),
                Integer.parseInt(metricTokens[3].trim()),
                Integer.parseInt(metricTokens[4].trim()),
                Integer.parseInt(metricTokens[5].trim()),
                Integer.parseInt(metricTokens[6].trim()),
                Integer.parseInt(metricTokens[7].trim()),
                Integer.parseInt(metricTokens[8].trim()),
                Integer.parseInt(metricTokens[9].trim())
            );
            // Check if the snapshot is in the time range
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (threadSnapshot.getTime() >= timeRange.getStartDate()
                    && threadSnapshot.getTime() <= timeRange.getEndDate()) {
                    inRange = true;
                    break;
                }
            }
            if (inRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("ThreadSnapshot")) {
                String[] columns = line.split(",");
                if (columns.length < 2) {
                    throw new IOException("Invalid snapshot line");
                }
                String[] timestampParts = columns[1].split(" ");
                if (timestampParts.length < 2) {
                    throw new IOException("Invalid snapshot timestamp");
                }
                long time = Long.parseLong(timestampParts[0]);
                if (time < timeRanges.get(0).getFrom() || time > timeRanges.get(timeRanges.size() - 1).getTo()) {
                    continue;
                }

                int numFiles = 0;
                int numOpenFiles = 0;
                int numLockedFiles = 0;
                int numFilesToBeClosed = 0;
                int numSleepingFiles = 0;
                for (int i = 2; i < columns.length; i++) {
                    String field = columns[i];
                    if (field.startsWith("numFiles=")) {
                        numFiles = Integer.parseInt(field.substring(8));
                    } else if (field.startsWith("numOpenFiles=")) {
                        numOpenFiles = Integer.parseInt(field.substring(12));
                    } else if (field.startsWith("numLockedFiles=")) {
                        numLockedFiles = Integer.parseInt(field.substring(13));
                    } else if (field.startsWith("numFilesToBeClosed=")) {
                        numFilesToBeClosed = Integer.parseInt(field.substring(18));
                    } else if (field.startsWith("numSleepingFiles=")) {
                        numSleepingFiles = Integer.parseInt(field.substring(15));
                    }
                }

                snapshots.add(new ThreadSnapshot(time, numFiles, numOpenFiles, numLockedFiles, numFilesToBeClosed, numSleepingFiles));
            }
        }
    }

    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = readSnapshot(line);
            if (snapshot != null && snapshot.getTimestamp() >= timeRanges.get(0).getStartTime() && snapshot.getTimestamp() <= timeRanges.get(0).getEndTime()) {
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}
